/**
 * The usage notes in French.
 *
 * Keyed by the English note exactly as the card carries it. A note missing
 * from here shows its English, so this file is filled in batches without any
 * card ever going blank — see usageNotes.ts for how it is loaded and why it
 * is not part of the interface tables.
 *
 * Fourteen thousand notes exist. This holds the ones translated so far, and
 * check-usage-notes prints how far along each language is on every build.
 */
export const USE_FR: Record<string, string> = {
  "'abschleppen' — to tow. Colloquially it also means pulling someone in a bar.": "'abschleppen' — remorquer. Familièrement, cela veut aussi dire lever quelqu'un dans un bar.",
  "'angesagt sein' — forecast, announced. Also slang for what's currently trendy.": "'angesagt sein' — annoncé, prévu. En argot aussi : ce qui est tendance en ce moment.",
  "'auf den Cent genau' is the fixed phrase — a virtue in a shop, a friendship-killer at a table. 'abrechnen' is the verb for settling up, and this is the polite way to call off over-precise splitting.": "'auf den Cent genau' est l'expression figée — une vertu en magasin, un tueur d'amitié à table. 'abrechnen' est le verbe pour régler les comptes, et voici la façon polie de renoncer à un partage au centime près.",
  "'auf etwas stehen' — to be into something. Informal, current, and used constantly.": "'auf etwas stehen' — être fan de quelque chose. Informel, actuel, employé sans arrêt.",
  "'Auf etwas stehen' = to be into something. Informal fan talk; works for genres, bands, and people.": "'Auf etwas stehen' = être fan de quelque chose. Parler de fan, informel ; vaut pour les genres, les groupes et les gens.",
  "'auf jemanden aufpassen' covers cats, kids and luggage alike. Plain present tense is how favours get asked between friends — no 'könntest du bitte' needed.": "'auf jemanden aufpassen' vaut pour les chats, les enfants et les bagages. C'est au présent simple qu'on demande un service entre amis — pas besoin de 'könntest du bitte'.",
  "'aufgewacht sein' as conspiracist self-description; comprehension only — hearing this is a warning sign": "'aufgewacht sein' comme autodescription complotiste ; pour la compréhension seulement — l'entendre est un signal d'alarme",
  "'bedeuten' for meaning. 'Was heißt das?' is the more casual version and just as correct.": "'bedeuten' pour le sens. 'Was heißt das?' est la version plus décontractée, tout aussi correcte.",
  "'bei jemandem was offen haben' = to have something outstanding with someone — friendly and vague, so you avoid the heavy word 'Schulden'. Works in both directions: 'Du hast noch was bei mir offen.'": "'bei jemandem was offen haben' = avoir quelque chose en suspens avec quelqu'un — amical et flou, pour éviter le mot lourd de 'Schulden'. Ça marche dans les deux sens : 'Du hast noch was bei mir offen.'",
  "'Bei uns' = in my country/family. 'Riesenthema' (giant topic) is casual and vivid — good for explaining your own culture.": "'Bei uns' = dans mon pays ou ma famille. 'Riesenthema' (sujet géant) est décontracté et imagé — parfait pour expliquer sa propre culture.",
  "'blank sein' = to have literally nothing left — a notch below 'pleite' and very casual. Friends and family only; never to a colleague or a landlord.": "'blank sein' = n'avoir littéralement plus rien — un cran en dessous de 'pleite' et très décontracté. Amis et famille seulement ; jamais à un collègue ou à un propriétaire.",
  "'borgen' — to lend informally between friends; 'leihen' works too. The dative person comes first: borgst du MIR.": "'borgen' — prêter de façon informelle entre amis ; 'leihen' marche aussi. La personne au datif vient en premier : borgst du MIR.",
  "'Das Match' — loan for a full competitive game; 'ist Schluss' = are we done. Casual.": "'Das Match' — emprunt pour une partie de compétition entière ; 'ist Schluss' = c'est terminé. Décontracté.",
  "'davon' avoids repeating the product name after pointing or asking a question about it.": "'davon' évite de répéter le nom du produit après l'avoir montré ou après avoir posé une question dessus.",
  "'davon' refers to an amount of the thing already being discussed and avoids repeating its name.": "'davon' renvoie à une quantité de la chose déjà évoquée et évite d'en répéter le nom.",
  "'der Ansprechpartner / die Ansprechpartnerin' — the person you go to about a thing — is unavoidable in German work life and has no snappy English equivalent. It's also the standard line in every out-of-office reply.": "'der Ansprechpartner / die Ansprechpartnerin' — la personne à qui l'on s'adresse pour une chose — est incontournable dans la vie professionnelle allemande et n'a pas d'équivalent concis en anglais. C'est aussi la phrase standard de tout message d'absence.",
  "'Der Hammer' = the standard casual superlative for events. Informal, all ages under about 50.": "'Der Hammer' = le superlatif décontracté habituel pour un événement. Informel, chez les moins de 50 ans environ.",
  "'Der Ping' — English loan, no alternative. 'übel' is youth slang for 'terrible'.": "'Der Ping' — emprunt à l'anglais, sans équivalent. 'übel' est de l'argot des jeunes pour 'atroce'.",
  "'die Couch' and 'das Sofa' are both everyday words — Couch sounds a shade more casual, Sofa a shade more neutral, and which one you hear depends on the household and the region more than on the setting. Said with mild guilt or open pride depending on the week you've had.": "'die Couch' et 'das Sofa' sont deux mots du quotidien — Couch sonne un cran plus décontracté, Sofa un cran plus neutre, et lequel on entend dépend du foyer et de la région plus que du contexte. Dit avec un peu de culpabilité ou une fierté assumée, selon la semaine qu'on a eue.",
  "'die Trotzphase' is the standard, slightly clinical German term for the tantrum years — describing, not complaining, which is why parents say it about their own kids without embarrassment. 'voll' is the casual spoken intensifier.": "'die Trotzphase' est le terme allemand standard, un peu clinique, pour l'âge des colères — descriptif et non plaintif, c'est pourquoi les parents l'emploient sans gêne pour leurs propres enfants. 'voll' est l'intensificateur décontracté à l'oral.",
  "'dir' means you are choosing it for yourself; 'Such was aus' also works. 'aus' moves to the end. This is the warm, informal way to offer someone a choice.": "'dir' signifie que tu choisis pour toi-même ; 'Such was aus' marche aussi. 'aus' passe à la fin. C'est la façon chaleureuse et informelle de laisser choisir quelqu'un.",
  "'doch mal' turns the instruction into a casual suggestion. 'anrufen' splits around the person being called.": "'doch mal' transforme la consigne en suggestion décontractée. 'anrufen' se sépare autour de la personne appelée.",
  "'doppelt' — double. 'Menge' is a quantity, and colloquially 'a lot'.": "'doppelt' — double. 'Menge' est une quantité, et familièrement 'beaucoup'.",
  "'dran sein' — to be next in turn. Compact, informal and used constantly.": "'dran sein' — être le prochain à passer. Compact, informel, employé sans arrêt.",
  "'dran' (= daran) is the ultra-casual kitchen way to say 'onto it'; how home cooks actually talk, never written in recipes.": "'dran' (= daran) est la forme ultra-décontractée de cuisine pour 'dessus' ; c'est ainsi que parlent vraiment les cuisiniers amateurs, jamais écrit dans les recettes.",
  "'draufschauen' — to look at it. Colloquial and separable.": "'draufschauen' — y jeter un œil. Familier et à particule séparable.",
  "'drücken' is the everyday word for hugging — warmer and more casual than 'umarmen'. Also in goodbyes and texts: 'Ich drück dich!' = hugs!": "'drücken' est le mot courant pour serrer dans ses bras — plus chaleureux et plus décontracté que 'umarmen'. Aussi dans les adieux et les messages : 'Ich drück dich!' = je te fais un câlin !",
  "'Du hast einen guten Musikgeschmack' is a real compliment between friends or on a date.": "'Du hast einen guten Musikgeschmack' est un vrai compliment entre amis ou lors d'un rendez-vous.",
  "'durch sein' — colloquially done for: soaked, worn out, finished.": "'durch sein' — familièrement fichu : trempé, usé, fini.",
  "'duzen' — to address someone as du. THE sentence for crossing from formal to informal. Traditionally the older person or the senior one offers it.": "'duzen' — tutoyer quelqu'un. LA phrase pour passer du vouvoiement au tutoiement. Traditionnellement, c'est la personne la plus âgée ou la plus haut placée qui la propose.",
  "'eigentlich' — the casual opener for a serious adult conversation.": "'eigentlich' — l'entrée en matière décontractée d'une conversation sérieuse entre adultes.",
  "'ein schlechtes Gewissen haben' = to feel guilty. The second cancellation needs this sentence; the third needs it plus a concrete new date attached, or the friendship quietly cools.": "'ein schlechtes Gewissen haben' = culpabiliser. La deuxième annulation exige cette phrase ; la troisième, cette phrase plus une nouvelle date concrète, sinon l'amitié se refroidit en silence.",
  "'einschlafen' means to fall asleep, but about a habit, a group chat or a friendship it means it quietly died — no decision, no announcement. The gentlest way to admit you stopped going.": "'einschlafen' veut dire s'endormir, mais pour une habitude, une conversation de groupe ou une amitié, cela signifie qu'elle s'est éteinte en silence — sans décision, sans annonce. La façon la plus douce d'avouer qu'on n'y va plus.",
  "'Elfer' is the casual clip everyone uses in speech": "'Elfer' est l'abréviation décontractée que tout le monde emploie à l'oral",
  "'Er ist trocken' is THE standard, respectful phrase for a recovering alcoholic who no longer drinks — not slang, not euphemism.": "'Er ist trocken' est LA formule standard et respectueuse pour un alcoolique abstinent qui ne boit plus — ni argot, ni euphémisme.",
  "'etwas aufrechnen' = to offset one thing against another, and between friends it's an accusation. This is the German way of saying the friendship is worth more than the four euros.": "'etwas aufrechnen' = compenser une chose par une autre, et entre amis c'est un reproche. C'est la manière allemande de dire que l'amitié vaut plus que les quatre euros.",
  "'ewig' — eternally, used casually for 'ages'. 'laden' for loading.": "'ewig' — éternellement, employé de façon décontractée pour 'une éternité'. 'laden' pour le chargement.",
  "'ey' at the end is the all-purpose spoken groan of exasperation — extremely common, extremely casual, never written anywhere official. 'ausgeloggt' beats the technically correct 'abgemeldet' in real speech.": "'ey' à la fin est le grognement oral d'exaspération à tout faire — extrêmement courant, extrêmement décontracté, jamais écrit dans un cadre officiel. 'ausgeloggt' l'emporte à l'oral réel sur le techniquement correct 'abgemeldet'.",
  "'fertig sein' about a person means finished in the sense of nothing left in the tank. Blunt but affectionate between friends and flatmates — say it to your boss and it's simply an insult.": "'fertig sein' à propos d'une personne veut dire qu'il ne reste plus rien dans le réservoir. Franc mais affectueux entre amis et colocataires — dit à son chef, c'est simplement une insulte.",
  "'fies' is the mean-spirited one — sharper than 'gemein' and very spoken. Between friends it's often half-admiring after a brutal joke; said flat, with no smile, it's completely serious.": "'fies' est le mot vraiment méchant — plus tranchant que 'gemein' et très oral. Entre amis, il est souvent à moitié admiratif après une vanne brutale ; dit à plat, sans sourire, il est tout à fait sérieux.",
  "'finden' + person is the safest everyday verdict — claims no friendship, implies no attraction. Spoken German drops the -e ('ich find'). Watch the gap: 'echt nett' is genuine, while bare 'ganz nett' is faint praise.": "'finden' + personne est le verdict quotidien le plus sûr — n'affirme aucune amitié, ne suggère aucune attirance. À l'oral, le -e tombe ('ich find'). Attention à l'écart : 'echt nett' est sincère, tandis que 'ganz nett' tout seul est un éloge tiède.",
  "'frei Schnauze' — literally free snout: no recipe, pure instinct. Wonderfully casual.": "'frei Schnauze' — littéralement museau libre : pas de recette, rien que l'instinct. Merveilleusement décontracté.",
  "'für Samstag' — booked for a day. A Transporter needs no lorry licence, which is why friends get asked.": "'für Samstag' — réservé pour une journée. Un Transporter ne demande pas de permis poids lourd, d'où la sollicitation des amis.",
  "'gar nicht erst' — not even starting. Avoiding the problem entirely.": "'gar nicht erst' — ne même pas commencer. Éviter complètement le problème.",
  "'geholt werden' = to get collected. Bags out too early get ripped open by crows overnight, and the whole street can then see whose rubbish it was — which is why this comes out slightly urgent rather than casual.": "'geholt werden' = être ramassé. Les sacs sortis trop tôt sont éventrés par les corneilles pendant la nuit, et toute la rue voit alors à qui appartenaient les ordures — d'où le ton légèrement pressant plutôt que décontracté.",
  "'glatt' — slippery with ice. The winter warning Germans text each other.": "'glatt' — verglacé, glissant. L'avertissement d'hiver que les Allemands s'envoient par texto.",
  "'gläubig' — devout. Said plainly, this ends no friendships in Germany.": "'gläubig' — croyant, pratiquant. Dit simplement, cela ne brise aucune amitié en Allemagne.",
  "'gucken' is the casual everyday verb (north/central); the south says 'schauen'": "'gucken' est le verbe décontracté du quotidien (nord et centre) ; le sud dit 'schauen'",
  "'Hä?' — bafflement, rising tone. Rude to teachers, standard between friends. 'Sinn ergeben' — to make sense.": "'Hä?' — perplexité, ton montant. Impoli envers un enseignant, standard entre amis. 'Sinn ergeben' — avoir du sens.",
  "'halbe-halbe' is common informal German for dividing something into two equal parts.": "'halbe-halbe' est de l'allemand informel courant pour partager quelque chose en deux parts égales.",
  "'hinkriegen' — to manage or pull something off. Informal, warm and extremely common.": "'hinkriegen' — arriver à faire quelque chose, y parvenir. Informel, chaleureux et extrêmement courant.",
  "'hinkriegen' is the casual everyday 'to manage, to pull off' — 'schaffen' is a shade more effortful and formal. The tacked-on 'echt' stops it sounding like an automatic pep talk: it means 'I actually believe that.'": "'hinkriegen' est le mot décontracté du quotidien pour y arriver, réussir — 'schaffen' est un cran plus laborieux et plus formel. Le 'echt' ajouté empêche que cela sonne comme un encouragement automatique : cela veut dire 'je le crois vraiment'.",
  "'Ich meinte damit, dass ...' states the intended meaning directly and avoids an unnecessarily heavy sentence frame.": "'Ich meinte damit, dass ...' énonce directement le sens voulu et évite une structure de phrase inutilement lourde.",
  "'in einfach' is colloquial and slightly jokey — asking for simpler words, not slower speech. Germans find it charming from a learner; 'Leichte Sprache' even exists as an official concept.": "'in einfach' est familier et un peu blagueur — on demande des mots plus simples, pas un débit plus lent. Les Allemands trouvent cela charmant chez un apprenant ; la 'Leichte Sprache' existe même comme notion officielle.",
  "'jeder zahlt seins' — the German default among friends. No awkwardness; it's the system.": "'jeder zahlt seins' — la règle par défaut entre amis en Allemagne. Rien de gênant : c'est le système.",
  "'jemandem etwas abkaufen' = to buy someone's story. Warm rather than confrontational between close friends, because it proves you've been paying attention — but presumptuous to an acquaintance.": "'jemandem etwas abkaufen' = gober l'histoire de quelqu'un. Chaleureux plutôt que frontal entre amis proches, parce que cela prouve qu'on écoutait — mais présomptueux avec une simple connaissance.",
  "'jemanden anstecken' = to pass your bug on. 'bloß' in a command is the urgent flavour — said with an arm held out, it's half genuine warning, half joke.": "'jemanden anstecken' = refiler son microbe. 'bloß' dans un ordre donne la note d'urgence — dit avec le bras tendu, c'est mi-avertissement sincère, mi-plaisanterie.",
  "'jemanden unter Druck setzen' is the standard phrase for creating pressure; urgency is a common warning sign.": "'jemanden unter Druck setzen' est la tournure standard pour faire pression ; l'urgence est un signal d'alarme fréquent.",
  "'jemanden vollquatschen' = to talk at someone non-stop. The standard climbdown once the rant runs out of steam. Casual, friends only.": "'jemanden vollquatschen' = tenir la jambe à quelqu'un sans arrêt. Le repli habituel quand le monologue s'essouffle. Décontracté, entre amis seulement.",
  "'jemanden von der Seite anmachen' = to start on someone unprovoked, on the street or on the train. Street-level slang, not office German.": "'jemanden von der Seite anmachen' = agresser quelqu'un sans raison, dans la rue ou dans le train. Argot de la rue, pas de l'allemand de bureau.",
  "'Jetzt reicht's' is the short version, and the last warning before a row.": "'Jetzt reicht's' est la version courte, et le dernier avertissement avant la dispute.",
  "'Keep your ears stiff' — parting encouragement to someone facing a hard stretch. Warm, informal, and said at doors.": "'Garde les oreilles droites' — encouragement d'adieu à quelqu'un qui affronte une période difficile. Chaleureux, informel, dit sur le pas de la porte.",
  "'kein ... mehr' means there is none left. 'Klopapier' is the ordinary informal word used at home.": "'kein ... mehr' signifie qu'il n'en reste plus. 'Klopapier' est le mot informel ordinaire à la maison.",
  "'Kein Thema' — not a topic: it doesn't even need discussing. Friendship in two words.": "'Kein Thema' — pas un sujet : il n'y a même pas à en discuter. L'amitié en deux mots.",
  "'keinen Nerv für etwas haben' = to have no patience or energy left for something — paperwork, drama, a discussion. Watch the preposition: 'dafür', never 'dazu'. Colloquial and mildly exasperated; extremely common and rarely taught.": "'keinen Nerv für etwas haben' = ne plus avoir la patience ni l'énergie pour quelque chose — paperasse, drame, discussion. Attention à la préposition : 'dafür', jamais 'dazu'. Familier et légèrement excédé ; extrêmement courant et rarement enseigné.",
  "'knapp' covers anything in short supply — time, money, a train connection. Here it's the warning shot before you either turn up breathless or cancel.": "'knapp' vaut pour tout ce qui manque — le temps, l'argent, une correspondance. Ici, c'est le coup de semonce avant d'arriver hors d'haleine ou d'annuler.",
  "'Land unter' comes from coastal flood warnings and means properly overwhelmed. Casual — for colleagues, not for clients.": "'Land unter' vient des alertes aux inondations côtières et signifie complètement débordé. Décontracté — pour des collègues, pas pour des clients.",
  "'laufen' is the verb for films showing — 'Der läuft noch' = it's still on. The 'denn ... so' pair turns it into a casual browse instead of a demand.": "'laufen' est le verbe pour les films à l'affiche — 'Der läuft noch' = il passe encore. Le couple 'denn ... so' en fait un parcours décontracté plutôt qu'une exigence.",
  "'lieb' is THE everyday German word for kind-hearted — warmer than 'nett', which can be faint praise ('ganz nett' is nearly an insult). Used about friends, grandmothers, children and helpful strangers alike.": "'lieb' est LE mot allemand du quotidien pour bon, au grand cœur — plus chaleureux que 'nett', qui peut être un éloge tiède ('ganz nett' frôle l'insulte). On l'emploie pour des amis, des grands-mères, des enfants et des inconnus serviables.",
  "'Lust haben auf + Akkusativ' ('Lust auf Kino?') or 'Lust, etwas zu tun'. This is the neutral everyday version — 'kein Bock' says the same thing in slang and is too casual for your boss or your landlord.": "'Lust haben auf + accusatif' ('Lust auf Kino?') ou 'Lust, etwas zu tun'. C'est la version neutre du quotidien — 'kein Bock' dit la même chose en argot et est trop décontracté pour votre chef ou votre propriétaire.",
  "'mal' makes the command sound casual; use 'in die Ecke' when directing light into it.": "'mal' rend l'ordre décontracté ; on emploie 'in die Ecke' quand on y dirige la lumière.",
  "'mal' softens the imperative into a casual request; masculine object is 'deinen Benutzernamen'.": "'mal' adoucit l'impératif en demande décontractée ; l'objet masculin est 'deinen Benutzernamen'.",
  "'mal' turns an offer into something casual. Two seconds, no commitment.": "'mal' rend l'offre décontractée. Deux secondes, sans engagement.",
  "'Man sieht sich' — literally one sees oneself — is the standard casual sign-off when no date is fixed.": "'Man sieht sich' — littéralement on se voit — est la formule d'adieu décontractée standard quand aucune date n'est fixée.",
  "'mitnehmen' is separable; in the informal imperative, 'mit' lands at the end.": "'mitnehmen' est à particule séparable ; à l'impératif informel, 'mit' se retrouve à la fin.",
  "'neben der Spur sein' — literally 'off the track' — is the everyday idiom for someone distracted, off, not themselves. Affectionate between friends; 'irgendwie' softens it further. Note the sharper cousin 'völlig neben der Spur', which means someone is way off base.": "'neben der Spur sein' — littéralement 'à côté de la trace' — est l'expression courante pour quelqu'un de distrait, à côté de la plaque, pas dans son assiette. Affectueux entre amis ; 'irgendwie' l'adoucit encore. Attention au cousin plus dur, 'völlig neben der Spur', qui veut dire complètement à côté.",
  "'Nie im Leben' = never in a million years; 'legit' is borrowed straight from English gaming slang. The standard disbelief formula.": "'Nie im Leben' = jamais de la vie ; 'legit' est emprunté tel quel à l'argot anglais du gaming. La formule standard de l'incrédulité.",
  "'nix für ungut' (spoken form of 'nichts für ungut') = no hard feelings, tacked on before or after the blow. Blunt but not hostile — fine with friends; with a boss drop it and use 'Da muss ich widersprechen.'": "'nix für ungut' (forme orale de 'nichts für ungut') = sans rancune, ajouté avant ou après le coup. Franc mais pas hostile — ça passe entre amis ; avec un chef, on le laisse tomber et on dit 'Da muss ich widersprechen.'",
  "'Pass auf!' is the fastest warning; separable 'aufpassen' becomes 'pass ... auf'.": "'Pass auf!' est l'avertissement le plus rapide ; le séparable 'aufpassen' devient 'pass ... auf'.",
  "'quatschen' = to chat, casual and affectionate; 'richtig' promises more than this doorstep version. Sometimes genuinely meant, sometimes not — Germans read it roughly the way English speakers read 'we should get coffee'.": "'quatschen' = bavarder, décontracté et affectueux ; 'richtig' promet plus que cette version sur le pas de la porte. Parfois sincère, parfois non — les Allemands le lisent à peu près comme les anglophones lisent 'we should get coffee'.",
  "'rauf und runter' = over and over — how Germans confess an obsession with a song or a show ('Die Serie hab ich rauf und runter geguckt'). Casual, affectionate, no negative edge at all.": "'rauf und runter' = en boucle — c'est ainsi que les Allemands avouent une obsession pour une chanson ou une série ('Die Serie hab ich rauf und runter geguckt'). Décontracté, affectueux, sans la moindre nuance négative.",
  "'rausfliegen' — from the fuse pack, here about a back. Colloquial and instantly understood.": "'rausfliegen' — venu du lot sur les fusibles, ici pour un dos. Familier et compris immédiatement.",
  "'rumhängen' (from 'herumhängen') = to hang about doing nothing. Casual and slightly teenage — perfect between friends and partners, odd in front of your boss.": "'rumhängen' (de 'herumhängen') = traîner sans rien faire. Décontracté et un peu ado — parfait entre amis et en couple, bizarre devant son chef.",
  "'Sag bloß!' is delighted disbelief, not a real request to speak. The mock reproach after it is a compliment in disguise: it says the news was too good not to have reached you sooner. Friends and family only — to a colleague it sounds nosy.": "'Sag bloß!' exprime une incrédulité ravie, pas une vraie demande de parler. Le faux reproche qui suit est un compliment déguisé : il dit que la nouvelle était trop belle pour ne pas t'être parvenue plus tôt. Amis et famille seulement — à un collègue, cela sonne indiscret.",
  "'schauen' or 'gucken' — gucken is more casual. No preposition before the platform.": "'schauen' ou 'gucken' — gucken est plus décontracté. Pas de préposition devant la plateforme.",
  "'schlapp' (colloquial) = run-down, drained; 'kaum' = barely.": "'schlapp' (familier) = à plat, vidé ; 'kaum' = à peine.",
  "'schwurbeln' is the current word for conspiracy-rambling; informal, everywhere since the pandemic": "'schwurbeln' est le mot actuel pour le délire complotiste ; informel, partout depuis la pandémie",
  "'sich anfühlen' is used for the experience ('Wie hat sich das angefühlt?'), 'sich fühlen' for the person ('Wie fühlst du dich?'). Warm and a little earnest — save it for friends, not for the colleague telling you about their commute.": "'sich anfühlen' s'emploie pour l'expérience ('Wie hat sich das angefühlt?'), 'sich fühlen' pour la personne ('Wie fühlst du dich?'). Chaleureux et un peu sérieux — gardez-le pour les amis, pas pour le collègue qui raconte son trajet.",
  "'sich aufs Ohr hauen' — literally to throw yourself onto your ear. Casual and a bit blokey, for friends and flatmates; 'ein Nickerchen machen' is the neutral way to describe the same twenty minutes.": "'sich aufs Ohr hauen' — littéralement se jeter sur l'oreille. Décontracté et un peu potache, pour les amis et les colocataires ; 'ein Nickerchen machen' décrit les mêmes vingt minutes de façon neutre.",
  "'Sich ein Haustier anschaffen' = to get a pet. Affectionate casual slang: 'das Fellbaby' (fur baby).": "'Sich ein Haustier anschaffen' = prendre un animal. Argot affectueux et décontracté : 'das Fellbaby' (bébé à poils).",
  "'sich etwas kaputt machen' = to wreck a body part — casual, slightly dramatic, used for backs and knees above all. 'Unkraut jäten' = to weed.": "'sich etwas kaputt machen' = se bousiller une partie du corps — décontracté, un peu dramatique, surtout pour le dos et les genoux. 'Unkraut jäten' = désherber.",
  "'Sich etwas ziehen' = to download, distinctly casual register; the standard buddy advice before a risky purchase.": "'Sich etwas ziehen' = télécharger, registre nettement décontracté ; le conseil de pote standard avant un achat risqué.",
  "'sich etwas ziehen' is slang for downloading; more neutral: 'runterladen' or the loan verb 'downloaden' — all three are common.": "'sich etwas ziehen' est de l'argot pour télécharger ; plus neutre : 'runterladen' ou le verbe emprunté 'downloaden' — les trois sont courants.",
  "'sich irren' — the dignified admission, equally at home in a meeting and in the kitchen. Blunter and more colloquial: 'Ich lag komplett falsch.' Never 'Ich war falsch' — that isn't German.": "'sich irren' — l'aveu digne, aussi à sa place en réunion qu'à la cuisine. Plus franc et plus familier : 'Ich lag komplett falsch.' Jamais 'Ich war falsch' — ce n'est pas de l'allemand.",
  "'sich reinsteigern' = to spiral into something; informal, the natural way to describe the rabbit-hole process": "'sich reinsteigern' = s'enfoncer dans quelque chose ; informel, la façon naturelle de décrire l'engrenage",
  "'sicherheitshalber' explains that you are checking to avoid an unnecessary mistake.": "'sicherheitshalber' explique qu'on vérifie pour éviter une erreur inutile.",
  "'spinnen' — literally to spin — is the everyday verb for being crazy. Between friends it is affectionate; at a stranger it is an insult.": "'spinnen' — littéralement filer la laine — est le verbe courant pour dire qu'on est fou. Entre amis c'est affectueux ; à un inconnu, c'est une insulte.",
  "'sportlich' — sporty, and also 'smart-casual' about clothes. Both are common.": "'sportlich' — sportif, et aussi 'smart casual' pour les vêtements. Les deux sont courants.",
  "'Strafzettel' — penalty slip. Also 'Knöllchen' colloquially, which sounds far too sweet for what it is.": "'Strafzettel' — le papillon d'amende. Familièrement aussi 'Knöllchen', qui sonne bien trop mignon pour ce que c'est.",
  "'total' as an intensifier is thoroughly spoken German and slightly informal.": "'total' comme intensificateur relève pleinement de l'allemand parlé et reste légèrement informel.",
  "'unbedingt' + colloquial 'was' (for etwas) = maximum urgency, zero formality. Best-friend register; the standard wind-up before gossip.": "'unbedingt' + le familier 'was' (pour etwas) = urgence maximale, formalité nulle. Registre des meilleurs amis ; l'élan standard avant les ragots.",
  "'unterschiedlich' — differing. Germans use it constantly to avoid overgeneralising.": "'unterschiedlich' — variable, divers. Les Allemands l'emploient sans arrêt pour éviter de généraliser.",
  "'Voll der/die X' is casual youth-speak amplification; pure banter register among friends and in voice chat.": "'Voll der/die X' est une amplification décontractée du parler jeune ; pur registre de vanne entre amis et en vocal.",
  "'voll' is THE everyday intensifier under about 40 — voll gut, voll nervig, voll teuer. Casual but harmless; drop it for the grown-up version: 'Das ist ziemlich langweilig.'": "'voll' est L'intensificateur du quotidien chez les moins de 40 ans — voll gut, voll nervig, voll teuer. Décontracté mais anodin ; on le retire pour la version adulte : 'Das ist ziemlich langweilig.'",
  "'von deinem' = from yours, dative with the noun simply dropped. Forks crossing the table are completely normal between friends, couples and family; with people you've just met, ask first rather than reach.": "'von deinem' = du tien, datif avec le nom simplement omis. Les fourchettes qui traversent la table sont tout à fait normales entre amis, en couple et en famille ; avec des gens que vous venez de rencontrer, demandez plutôt que de vous servir.",
  "'was trinken gehen' — the standard invitation. Casual, open-ended, no commitment implied.": "'was trinken gehen' — l'invitation standard. Décontractée, ouverte, sans engagement.",
  "'wegmachen' colloquially for putting something aside. 'mal' softens the announcement.": "'wegmachen' familièrement pour ranger quelque chose de côté. 'mal' adoucit l'annonce.",
  "'Wie hoch' for amounts of money. A completely normal question between German friends.": "'Wie hoch' pour les sommes d'argent. Une question tout à fait normale entre amis allemands.",
  "'wieder drauf haben' — colloquial and compact. Bike chains come off constantly.": "'wieder drauf haben' — familier et compact. Les chaînes de vélo déraillent sans arrêt.",
  "'Wofür' is the normal neutral form; 'für was' is regional or very casual.": "'Wofür' est la forme neutre normale ; 'für was' est régional ou très décontracté.",
  "'Zeit mitbringen' — the honest warning. Open hours mean open-ended waiting.": "'Zeit mitbringen' — l'avertissement honnête. Des horaires sans rendez-vous, c'est une attente sans fin.",
  "'zurückrufen' is separable: ich rufe dich zurück. 'mitten in was' (= in etwas) is casual spoken German; at work the same excuse is 'Ich bin gerade in einem Termin.'": "'zurückrufen' est à particule séparable : ich rufe dich zurück. 'mitten in was' (= in etwas) est de l'allemand parlé décontracté ; au travail, la même excuse devient 'Ich bin gerade in einem Termin.'",
  "'Zuschlagen' = to strike when a deal appears — THE verb for sale purchases, gaming or otherwise. Casual bragging register.": "'Zuschlagen' = sauter sur l'occasion quand une promo apparaît — LE verbe des achats en solde, gaming ou pas. Registre décontracté de la vantardise.",
  "'zwischen den Jahren' is the fixed expression for the dead week between Christmas and New Year, when half the country is away and nothing gets decided. Standard November small talk; 'eigentlich' keeps it casual rather than nosy.": "'zwischen den Jahren' est l'expression figée pour la semaine morte entre Noël et le Nouvel An, quand la moitié du pays est absente et que rien ne se décide. Small talk standard de novembre ; 'eigentlich' garde le ton décontracté plutôt qu'indiscret.",
  "\"Kiste\" is a crate or box, and colloquially any old thing. Say this before you sign for anything that looks tampered with.": "'Kiste' est une caisse ou un carton, et familièrement n'importe quel truc. Dites cela avant de signer pour quoi que ce soit qui semble avoir été ouvert.",
  "18+ conversational — the standard casual way to ask about turn-ons ('stehen auf + Akk'). Between partners or in open flirting, never at work.": "Conversation 18+ — la façon décontractée standard de demander ce qui excite quelqu'un ('stehen auf + accusatif'). Entre partenaires ou en flirt assumé, jamais au travail.",
  "A broad casual check-in about life, work or whatever is currently going on. The situation decides how wide the answer should be.": "Une prise de nouvelles large et décontractée sur la vie, le travail ou ce qui se passe en ce moment. C'est la situation qui décide de l'ampleur de la réponse.",
  "A broad casual question about someone's work, studies or life. It usually asks more than what they are doing this exact second.": "Une question large et décontractée sur le travail, les études ou la vie de quelqu'un. Elle porte généralement sur plus que ce qu'il fait à la seconde présente.",
  "A broad catch-up question about someone's current life. 'zurzeit' means these days or at present, and 'so' keeps the question casual.": "Une question large pour prendre des nouvelles de la vie actuelle. 'zurzeit' veut dire en ce moment, et 'so' garde la question décontractée.",
  "A casual event or venue question. 'mit wem' asks which person or group someone came with or is spending time with.": "Une question décontractée en soirée ou dans un lieu. 'mit wem' demande avec quelle personne ou quel groupe on est venu ou on passe du temps.",
  "A casual first-meeting question about whether someone comes from the local area. It is less broad than asking which country or city they come from.": "Une question décontractée à la première rencontre : est-ce que la personne est du coin ? Plus restreinte que demander de quel pays ou de quelle ville elle vient.",
  "A casual purpose question when someone has an object, tool, file or unusual plan.": "Une question décontractée sur le but, quand quelqu'un a un objet, un outil, un fichier ou un projet inhabituel.",
  "A casual question about an object when you do not know or do not need its exact name. 'Ding' is everyday but vague.": "Une question décontractée sur un objet quand on ignore ou qu'on n'a pas besoin de son nom exact. 'Ding' est courant mais vague.",
  "A colloquial fixed expression. It is not sexual in this use.": "Une expression figée familière. Elle n'a rien de sexuel dans cet emploi.",
  "A common getting-to-know-you question when either work or study could fit. Avoid it if the setting makes the answer obvious.": "Une question courante pour faire connaissance, quand travail ou études pourraient convenir tous les deux. À éviter si le contexte rend la réponse évidente.",
  "A common informal reassurance. It literally mentions your head, but the meaning is not to worry.": "Une phrase rassurante informelle et courante. Elle parle littéralement de la tête, mais veut dire : ne t'en fais pas.",
  "A common informal response to disappointing news or an annoying problem.": "Une réaction informelle courante à une nouvelle décevante ou à un problème agaçant.",
  "A common shortened suggestion to avoid deciding too early. A complete version is 'Warten wir erst mal ab'.": "Une suggestion abrégée courante pour ne pas décider trop tôt. La version complète est 'Warten wir erst mal ab'.",
  "A common use of sammeln among friends, at work or in a family.": "Un emploi courant de sammeln entre amis, au travail ou en famille.",
  "A considerate response to bad news when a casual reaction would feel too light.": "Une réponse pleine d'égards à une mauvaise nouvelle, quand une réaction décontractée paraîtrait trop légère.",
  "A direct informal question about ability. English keeps the main verb in its plain form after 'can': 'Can you do...?', never 'Can you to do...?'.": "Une question informelle et directe sur la capacité. En anglais, le verbe principal reste à la forme simple après 'can' : 'Can you do...?', jamais 'Can you to do...?'.",
  "A direct warning that a condition or necessary step cannot be skipped.": "Un avertissement direct : une condition ou une étape nécessaire ne peut pas être sautée.",
  "A kind boundary always names a new time — postponing without one is heard as a refusal. 'Ich schaff's nicht mehr' says you're out of capacity, not out of interest, which is the difference that keeps the friendship intact.": "Une limite bienveillante nomme toujours une nouvelle date — reporter sans en donner une s'entend comme un refus. 'Ich schaff's nicht mehr' dit que tu n'as plus de capacité, pas que tu n'as plus d'envie, et c'est cette différence qui préserve l'amitié.",
  "A later colloquial shortcut for when the restaurant context is already obvious. 'was' is spoken 'etwas' and can imply a table or some space, but it is less clear than 'Haben Sie noch einen Tisch frei?' — learn the explicit version first.": "Un raccourci familier plus tardif, quand le contexte du restaurant est déjà évident. 'was' est le 'etwas' oral et peut désigner une table ou un peu de place, mais c'est moins clair que 'Haben Sie noch einen Tisch frei?' — apprenez d'abord la version explicite.",
  "A natural follow-up after meeting two friends. 'seid ihr' addresses both people together.": "Une relance naturelle après avoir croisé deux amis. 'seid ihr' s'adresse aux deux à la fois.",
  "A natural urgent warning. German can use this short phrase without a verb when the danger is obvious.": "Un avertissement urgent naturel. L'allemand peut se passer de verbe quand le danger est évident.",
  "A natural warning to an animal gulping food. The situation supplies the missing verb, so German keeps it short.": "Un avertissement naturel à un animal qui engloutit sa nourriture. La situation fournit le verbe manquant, l'allemand reste donc bref.",
  "A normal informal request for a very short wait. Add 'bitte' when you want it to sound softer.": "Une demande informelle normale pour patienter très brièvement. Ajoutez 'bitte' pour l'adoucir.",
  "A practical check that helps the group avoid stopping again once the task has begun.": "Une vérification pratique qui évite au groupe de devoir s'arrêter à nouveau une fois lancé.",
  "A safety warning in frost, snow or freezing rain. 'glatt' does not always mean icy, so slippery is the broad translation.": "Un avertissement de sécurité en cas de gel, de neige ou de pluie verglaçante. 'glatt' ne veut pas toujours dire verglacé, d'où la traduction large par glissant.",
  "A serious accusation, not casual criticism.": "Une accusation grave, pas une critique en passant.",
  "A shade more emotional than 'keine Lust' — this is about your state, not the activity. Warning: between partners at night it means exactly what it means in English.": "Une nuance plus émotionnelle que 'keine Lust' — il s'agit de ton état, pas de l'activité. Attention : entre partenaires, le soir, cela veut dire exactement ce que cela veut dire en anglais.",
  "A short warning after treatment or when a pet worries a sore spot. The object is obvious, so German leaves it out.": "Un bref avertissement après un soin ou quand un animal tripote une plaie. L'objet est évident, l'allemand l'omet donc.",
  "A shortened vulgar dismissal. It can be joking only between very close friends with the right tone; otherwise it is an insult.": "Un rejet vulgaire abrégé. Il ne passe en plaisanterie qu'entre amis très proches, avec le bon ton ; sinon, c'est une insulte.",
  "A standard informal request. The favour itself normally follows immediately.": "Une demande informelle standard. Le service demandé suit normalement tout de suite.",
  "A standard Monday small-talk question with friends, classmates and colleagues you know.": "La question de small talk du lundi, entre amis, camarades de classe et collègues que l'on connaît.",
  "A standing offer between partners or close friends; warm, no drama.": "Une proposition toujours valable entre partenaires ou amis proches ; chaleureuse, sans drame.",
  "A very common casual follow-up when the first topic is finished and you want the conversation to continue.": "Une relance décontractée très courante quand le premier sujet est épuisé et qu'on veut poursuivre la conversation.",
  "A very common informal way to check whether a day suits someone.": "Une manière informelle très courante de demander si un jour convient à quelqu'un.",
  "abgefahren — driven off, worn. Also slang for 'amazing'; the tyre meaning is older.": "abgefahren — usé jusqu'à la corde. En argot aussi 'génial' ; le sens lié au pneu est plus ancien.",
  "Achtung! is the warning word; die Ampel = the traffic light, always feminine.": "Achtung! est le mot d'avertissement ; die Ampel = le feu tricolore, toujours féminin.",
  "Affectionate or dry, harmless — literally 'fun bird'. Said fondly, or deadpan when the joke was bad. Safe with anyone informal.": "Affectueux ou pince-sans-rire, anodin — littéralement 'oiseau rigolo'. Dit avec tendresse, ou à plat quand la blague était mauvaise. Sans risque avec n'importe qui, en registre informel.",
  "Affectionate teasing, harmless — partner, kids, close friends. Almost never stings; it implies fond exasperation, not stupidity.": "Taquinerie affectueuse, anodine — partenaire, enfants, amis proches. Ça ne pique presque jamais ; cela suggère une exaspération tendre, pas de la bêtise.",
  "Affectionate, harmless — for someone talking nonsense or clowning around. Partner, friends, kids. Warm, never a real insult.": "Affectueux, anodin — pour quelqu'un qui dit n'importe quoi ou fait le clown. Partenaire, amis, enfants. Chaleureux, jamais une vraie insulte.",
  "Afterwards": "Ensuite",
  "Agreeing": "Approuver",
  "Allotment neighbours — advisors, rivals and friends across one fence. Mostly all three.": "Voisins de jardin ouvrier — conseillers, rivaux et amis de part et d'autre d'une clôture. Le plus souvent les trois.",
  "Almost always plural; singular das Beziehungsproblem. Neutral, the word you use confiding in friends.": "Presque toujours au pluriel ; singulier das Beziehungsproblem. Neutre, le mot qu'on emploie en se confiant à des amis.",
  "also colloquially \"incredibly\": unwahrscheinlich gut": "familièrement aussi 'incroyablement' : unwahrscheinlich gut",
  "also colloquially \"massively\": tierisch gut": "familièrement aussi 'vachement' : tierisch gut",
  "always plural": "toujours au pluriel",
  "Among friends, immediately after the news. 'Mal' softens it into eager excitement, not a command.": "Entre amis, juste après la nouvelle. 'Mal' en fait de l'impatience enthousiaste, pas un ordre.",
  "An informal reaction to a plan failing, something breaking or another everyday setback.": "Une réaction informelle quand un plan échoue, que quelque chose casse ou qu'un contretemps du quotidien survient.",
  "Anglicism, under-40 casual; scrollen is fully naturalized for everyone, doomscrollen still youth-flavoured": "Anglicisme, décontracté chez les moins de 40 ans ; scrollen est pleinement naturalisé pour tous, doomscrollen garde une saveur jeune",
  "ANGRY — the final rung before consequences, and everyone hears it that way. Adults use it on each other too, where it lands as a real threat rather than a warning.": "EN COLÈRE — le dernier échelon avant les conséquences, et tout le monde l'entend ainsi. Les adultes se le disent aussi entre eux, où cela sonne comme une vraie menace plutôt qu'un avertissement.",
  "Ask two or more people for the story of how they first met. It can be about friends, a couple or colleagues.": "Demandez à deux personnes ou plus l'histoire de leur première rencontre. Cela peut concerner des amis, un couple ou des collègues.",
  "Asking for the bill": "Demander l'addition",
  "At the table, informal. One guest: 'Greif zu!' Signals the eating may begin.": "À table, informel. Pour un seul invité : 'Greif zu!' Cela signale qu'on peut commencer à manger.",
  "At the till": "À la caisse",
  "aufblasen — inflating. 'Hilf mir mal' — the casual recruiting of bystanders.": "aufblasen — gonfler. 'Hilf mir mal' — la façon décontractée d'enrôler ceux qui passent.",
  "aufdrängen — pressing something on someone. The warning before every market stroll.": "aufdrängen — imposer quelque chose à quelqu'un. L'avertissement avant chaque flânerie au marché.",
  "aufziehen — a storm pulling up. denn delivers the warning in plain word order.": "aufziehen — un orage qui se lève. denn livre l'avertissement dans un ordre des mots tout simple.",
  "Aus der Kirche austreten = to formally leave the church. Casually, mal austreten = to nip to the loo.": "Aus der Kirche austreten = quitter officiellement l'Église. En registre décontracté, mal austreten = filer aux toilettes.",
  "auslaufen — leaking out. 'hinüber sein' — colloquially beyond saving.": "auslaufen — fuir, s'écouler. 'hinüber sein' — familièrement, fichu.",
  "ausstrecken splits in the imperative; mal softens the order to a casual prompt. German uses die, not 'your', with body parts.": "ausstrecken se sépare à l'impératif ; mal adoucit l'ordre en simple invite décontractée. Avec les parties du corps, l'allemand emploie die, pas 'ton'.",
  "Banter": "Vannes",
  "beim Umzug = with the move. Moving house with friends (and pizza afterwards) is completely standard in Germany.": "beim Umzug = pour le déménagement. Déménager avec des amis (et pizza après) est tout à fait standard en Allemagne.",
  "beraten — advising. 'einen' — the colloquial accusative of man.": "beraten — conseiller. 'einen' — l'accusatif familier de man.",
  "Between friends: Kannst du mir zehn Euro borgen? Standard German prefers leihen.": "Entre amis : Kannst du mir zehn Euro borgen? L'allemand standard préfère leihen.",
  "Blunt but completely normal between partners and friends — German directness in action": "Franc mais tout à fait normal entre partenaires et amis — la franchise allemande à l'œuvre",
  "Blunt but standard dismissal of a politician. Strong opinion, casual delivery — fine between partners and friends. '...von ihr' for her.": "Franc mais standard comme rejet d'un politicien. Opinion tranchée, ton décontracté — ça passe en couple et entre amis. '...von ihr' pour elle.",
  "Blunt insult, literally a full fencepost. Friends-only register.": "Insulte brutale, littéralement un piquet de clôture entier. À réserver aux amis.",
  "Blunt self-criticism that admits your behaviour was bad. It can sound sincere among friends, but use a cleaner apology at work.": "Autocritique franche qui admet que votre comportement était mauvais. Elle peut sonner sincère entre amis, mais au travail, préférez des excuses plus nettes.",
  "borgen — the casual borrow-lend verb. die Leiter migrates between households like a shared pet.": "borgen — le verbe décontracté pour prêter et emprunter. die Leiter migre d'un foyer à l'autre comme un animal en garde partagée.",
  "Both a literal on-set announcement and a warning that everything from now on is Content; läuft = runs, the standard verb for recording devices.": "À la fois l'annonce littérale sur un tournage et l'avertissement que tout, désormais, est du Content ; läuft = tourne, le verbe standard pour les appareils d'enregistrement.",
  "Both forms are normal. 'Sinn ergeben' is the standard, register-neutral form; 'Sinn machen' is very common in everyday speech and informal writing. Negative: 'Das ergibt keinen Sinn' or conversational 'Das macht keinen Sinn'.": "Les deux formes sont normales. 'Sinn ergeben' est la forme standard, neutre de registre ; 'Sinn machen' est très courant à l'oral quotidien et à l'écrit informel. Au négatif : 'Das ergibt keinen Sinn' ou, en conversation, 'Das macht keinen Sinn'.",
  "bumming a cigarette; casual, smoker-to-smoker only": "taxer une cigarette ; décontracté, entre fumeurs seulement",
  "Buying time": "Gagner du temps",
  "Careful — between two people who might be dating, this IS the small confession, one step below 'Ich hab dich lieb'. Between friends it's plain and warm. Tone and timing carry the whole meaning.": "Attention — entre deux personnes qui se fréquentent peut-être, c'EST le petit aveu, un cran en dessous de 'Ich hab dich lieb'. Entre amis, c'est simple et chaleureux. Le ton et le moment portent tout le sens.",
  "Casual": "Décontracté",
  "Casual — and ambiguous by design: 'zocken' means both gambling and video gaming. Among under-40s the default reading is gaming; in a casino context it's gambling.": "Décontracté — et ambigu à dessein : 'zocken' signifie à la fois jouer de l'argent et jouer aux jeux vidéo. Chez les moins de 40 ans, la lecture par défaut est le jeu vidéo ; dans un casino, c'est le jeu d'argent.",
  "Casual — Ding literally means 'thing'": "Décontracté — Ding signifie littéralement 'chose'",
  "Casual — literally 'now we have the salad'": "Décontracté — littéralement 'maintenant on a la salade'",
  "Casual — literally 'that's not my beer'": "Décontracté — littéralement 'ce n'est pas ma bière'",
  "Casual — literally 'you had pig'": "Décontracté — littéralement 'tu as eu du cochon'",
  "Casual agreement": "Accord décontracté",
  "Casual and dramatic; often frustration rather than literal loss of control.": "Décontracté et dramatique ; souvent de la frustration plutôt qu'une vraie perte de contrôle.",
  "casual between friends; the English loans (Foundation, Concealer) are standard in German — French keeps 'fond de teint'": "décontracté entre amis ; les emprunts anglais (Foundation, Concealer) sont la norme en allemand — le français garde 'fond de teint'",
  "Casual check-in mid-explanation.": "Petite vérification décontractée en pleine explication.",
  "casual clipping of 'Prominenter' — everyday word": "abréviation décontractée de 'Prominenter' — mot de tous les jours",
  "Casual complaint, one hour in. Someone packed too much Brotzeit.": "Plainte décontractée au bout d'une heure. Quelqu'un a emporté trop de Brotzeit.",
  "casual compliment; stehen + dative = to suit someone": "compliment décontracté ; stehen + datif = aller bien à quelqu'un",
  "Casual criticism, mild to sharp depending on tone — from amused head-shake about a friend to genuine warning about a date.": "Critique décontractée, douce ou tranchante selon le ton — du hochement de tête amusé à propos d'un ami jusqu'à l'avertissement sérieux sur un rendez-vous.",
  "Casual date invite (better than formal 'Möchten Sie...')": "Invitation à un rendez-vous, ton décontracté (mieux que le formel 'Möchten Sie...')",
  "Casual dating vocabulary with friends. The verb is fully germanized: ghosten, geghostet.": "Vocabulaire de rencontres décontracté entre amis. Le verbe est entièrement germanisé : ghosten, geghostet.",
  "Casual dating-discourse talk, mostly among friends dissecting someone's behaviour. Anglicism, feminine in German: die Red Flag (French keeps it masculine: un red flag).": "Discussion décontractée sur les rencontres, surtout entre amis qui décortiquent le comportement de quelqu'un. Anglicisme, féminin en allemand : die Red Flag (le français le garde masculin : un red flag).",
  "casual Denglisch — 'Ich hab gecodet' is completely normal among devs": "denglisch décontracté — 'Ich hab gecodet' est tout à fait normal chez les développeurs",
  "Casual directive": "Consigne décontractée",
  "Casual du-register. This is the pattern the seed word needs: anstoßen AUF + Akkusativ (auf den Erfolg, aufs neue Jahr, auf dich). Separable, so the prefix lands at the end: wir stoßen darauf an. And keep eye contact while clinking.": "Registre du, décontracté. Voici le schéma dont ce mot a besoin : anstoßen AUF + accusatif (auf den Erfolg, aufs neue Jahr, auf dich). Séparable, donc le préfixe finit à la fin : wir stoßen darauf an. Et gardez le contact visuel en trinquant.",
  "Casual everyday goodbye — used everywhere in Germany": "Au revoir décontracté du quotidien — employé partout en Allemagne",
  "Casual everyday reassurance": "Petite phrase rassurante et décontractée du quotidien",
  "Casual favour between friends (du). 'drüberschauen' = give it a quick once-over.": "Petit service décontracté entre amis (du). 'drüberschauen' = y jeter un coup d'œil rapide.",
  "Casual for playing video games; in money contexts it means to gamble.": "Décontracté pour jouer aux jeux vidéo ; avec de l'argent, cela signifie parier.",
  "Casual goodbye — borrowed from Italian, extremely popular in Germany": "Au revoir décontracté — emprunté à l'italien, très répandu en Allemagne",
  "casual gym slang for lifting weights; 'pumpen gehen'": "argot décontracté de salle de sport pour soulever de la fonte ; 'pumpen gehen'",
  "Casual idiom, literally 'sponge over it' (wiping the slate): declares a small quarrel officially closed. Friends and partners, minor stuff only — don't 'Schwamm drüber' a real hurt.": "Expression décontractée, littéralement 'un coup d'éponge' (effacer l'ardoise) : déclare une petite dispute officiellement close. Amis et partenaires, pour les broutilles seulement — on ne passe pas l'éponge sur une vraie blessure.",
  "Casual imperative 'Investier' is common spoken German; full written form is 'Investiere'.": "L'impératif décontracté 'Investier' est courant à l'oral ; la forme écrite complète est 'Investiere'.",
  "Casual imperative 'Markier' is common in voice chat; after 'damit', 'verlaufen' goes to the end.": "L'impératif décontracté 'Markier' est courant en vocal ; après 'damit', 'verlaufen' passe à la fin.",
  "Casual imperative 'Setz' is short for 'Setze'; 'am' contracts dative 'an dem'.": "L'impératif décontracté 'Setz' abrège 'Setze' ; 'am' contracte le datif 'an dem'.",
  "Casual imperative of separable 'hinzufügen' is 'Füg ... hinzu'; the person being added is accusative 'mich'.": "L'impératif décontracté du séparable 'hinzufügen' est 'Füg ... hinzu' ; la personne ajoutée est à l'accusatif : 'mich'.",
  "Casual invite": "Invitation décontractée",
  "Casual kitchen-table economics; sich lohnen = to be worth it — very high-frequency verb": "Économie de coin de table, ton décontracté ; sich lohnen = en valoir la peine — verbe très fréquent",
  "casual loanword; einkaufen is the German verb": "emprunt décontracté ; einkaufen est le verbe allemand",
  "Casual media criticism among friends; sich aufregen über = to get worked up about — essential B1 verb": "Critique des médias, ton décontracté, entre amis ; sich aufregen über = s'énerver à propos de — verbe B1 indispensable",
  "casual money-vent to friends, du-register — the one informal line in this pack; the bank formally calls it 'Dispositionskredit'": "coup de gueule décontracté sur l'argent entre amis, registre du — la seule ligne informelle de ce lot ; la banque appelle cela officiellement 'Dispositionskredit'",
  "Casual opener": "Entrée en matière décontractée",
  "Casual opener for close friends": "Entrée en matière décontractée entre amis proches",
  "Casual opinion": "Avis exprimé de façon décontractée",
  "Casual pointing-at-things question with friends — how learners actually acquire everyday nouns. 'das Ding' = thingy.": "Question décontractée en montrant du doigt, entre amis — c'est ainsi que les apprenants acquièrent vraiment les noms du quotidien. 'das Ding' = le truc.",
  "Casual positive update": "Bonne nouvelle donnée sur un ton décontracté",
  "Casual pub folklore — 'angeblich' (supposedly) does the honest work here. It's a myth: the Konterbier only postpones the hangover, and needing one regularly is a recognised warning sign.": "Folklore de bistrot décontracté — c'est 'angeblich' (soi-disant) qui fait ici le travail honnête. C'est un mythe : la Konterbier ne fait que repousser la gueule de bois, et en avoir besoin régulièrement est un signal d'alarme reconnu.",
  "Casual register inside student life; durcharbeiten = work through without a break.": "Registre décontracté de la vie étudiante ; durcharbeiten = travailler sans faire de pause.",
  "Casual reminiscing; 'was los sein' = something happening.": "Souvenirs évoqués sur un ton décontracté ; 'was los sein' = il se passe quelque chose.",
  "Casual reply": "Réponse décontractée",
  "Casual request": "Demande décontractée",
  "Casual request to repeat": "Demande décontractée de répéter",
  "Casual self-intro": "Présentation de soi décontractée",
  "Casual slang command": "Ordre en argot décontracté",
  "Casual slang farewell": "Au revoir en argot décontracté",
  "Casual slang, friends only — two senses: \"count me out\" when plans are being made, or \"I'm off\" when you leave. From poker and reality TV, now everywhere among under-40s; abrupt to strangers or at work.": "Argot décontracté, entre amis seulement — deux sens : 'sans moi' quand des plans se font, ou 'j'y vais' quand on part. Venu du poker et de la téléréalité, aujourd'hui partout chez les moins de 40 ans ; abrupt avec des inconnus ou au travail.",
  "Casual speech drops the prefix: you 'schieben' a plan with a friend, you 'verschieben' a Termin with a doctor or a client. 'auf' + accusative for the new date.": "À l'oral décontracté, on laisse tomber le préfixe : on 'schiebt' un plan avec un ami, on 'verschiebt' un Termin chez le médecin ou avec un client. 'auf' + accusatif pour la nouvelle date.",
  "Casual spoken imperative 'Markier' is common; the tool follows dative 'mit einem Bleistift'.": "L'impératif oral décontracté 'Markier' est courant ; l'outil suit au datif : 'mit einem Bleistift'.",
  "Casual spoken; 'ich wechsel' instead of textbook 'ich wechsle' is normal in speech. 'Die Klasse' is standard, no English loan here.": "Oral décontracté ; 'ich wechsel' au lieu du 'ich wechsle' des manuels est normal à l'oral. 'Die Klasse' est standard, pas d'emprunt anglais ici.",
  "casual spoken; from sich fertig machen = sich zurechtmachen": "oral décontracté ; de sich fertig machen = se préparer, s'apprêter",
  "casual spoken; the machen-lassen pattern for anything done at a salon": "oral décontracté ; la tournure machen-lassen pour tout ce qui se fait chez le coiffeur",
  "casual, admiring; 'definiert' = lean and cut, more technical": "décontracté et admiratif ; 'definiert' = sec et dessiné, plus technique",
  "CASUAL, and generational — 'geil' originally meant horny and is now simply 'awesome' in everyday speech, but older relatives still wince. The 'Wie ... ist das denn!' frame takes any adjective: 'Wie süß ist das denn!', 'Wie teuer ist das denn!'": "DÉCONTRACTÉ, et affaire de génération — 'geil' signifiait à l'origine excité et veut simplement dire 'génial' à l'oral d'aujourd'hui, mais les parents âgés grimacent encore. Le cadre 'Wie ... ist das denn!' accepte n'importe quel adjectif : 'Wie süß ist das denn!', 'Wie teuer ist das denn!'",
  "Casual, concerned — 'die Spielothek' (slot arcade) sits several rungs below 'das Casino' in register and respectability; the sentence itself signals worry.": "Décontracté et inquiet — 'die Spielothek' (salle de machines à sous) se situe plusieurs crans en dessous de 'das Casino' en registre et en respectabilité ; la phrase elle-même signale l'inquiétude.",
  "Casual, enthusiastic. 'Der Wahnsinn' is the go-to superlative among friends.": "Décontracté, enthousiaste. 'Der Wahnsinn' est le superlatif de référence entre amis.",
  "casual, everyday; \"dezent\" is THE German word for understated — makeup, jewellery, perfume, clothes — and its opposite is \"auffällig\". Fills the gap in this pack between the salon requests and the compliments: how you describe your own look. 'sich schminken' changes with the person: 'ich schminke mich', 'du schminkst dich'.": "décontracté, quotidien ; 'dezent' est LE mot allemand pour discret — maquillage, bijoux, parfum, vêtements — et son contraire est 'auffällig'. Il comble ici l'écart entre les demandes au salon et les compliments : comment décrire son propre look. 'sich schminken' change avec la personne : 'ich schminke mich', 'du schminkst dich'.",
  "casual, everyday; der Lidstrich is the German word, Eyeliner is what people say": "décontracté, quotidien ; der Lidstrich est le mot allemand, mais on dit Eyeliner",
  "Casual, exasperated. Standard lakeside-evening lament; 'fressen' (animal eating) makes it vivid.": "Décontracté, exaspéré. La plainte classique du soir au bord du lac ; 'fressen' (manger, pour un animal) rend l'image vive.",
  "Casual, mild — amused disbelief among friends and family. Friendly in tone, but too blunt for strangers or superiors.": "Décontracté, doux — incrédulité amusée entre amis et en famille. Ton amical, mais trop direct pour des inconnus ou des supérieurs.",
  "Casual, mild — the adjective version, interchangeable with 'einen Kater haben'. Fine in any informal setting.": "Décontracté, doux — la version adjectivale, interchangeable avec 'einen Kater haben'. Correct dans tout cadre informel.",
  "Casual, mild — the standard morning-after sentence among friends and relaxed colleagues. 'fett' intensifies it.": "Décontracté, doux — la phrase standard du lendemain matin entre amis et collègues détendus. 'fett' l'intensifie.",
  "Casual, mild — the standard verdict on a Flachwitz. Said with a groan and half a smile; friends and colleagues.": "Décontracté, doux — le verdict standard sur un Flachwitz. Dit avec un grognement et un demi-sourire ; amis et collègues.",
  "Casual, playful — everyday micro-betting between friends. 'die Wette' = the bet; the structure was immortalized by the TV show 'Wetten, dass..?'.": "Décontracté, joueur — le micro-pari quotidien entre amis. 'die Wette' = le pari ; la structure a été immortalisée par l'émission de télévision 'Wetten, dass..?'.",
  "Casual, relieved-triumphant, to friends. 'überstehen' = to survive something unpleasant.": "Décontracté, soulagé et triomphant, entre amis. 'überstehen' = survivre à quelque chose de désagréable.",
  "Casual, relieved. 'Kriegen' is the everyday spoken 'bekommen'. Rare Bahn stories have happy endings — savour them.": "Décontracté, soulagé. 'Kriegen' est le 'bekommen' de tous les jours à l'oral. Rares sont les histoires de train qui finissent bien — savourez-les.",
  "Casual, teasing — literally 'do you have tomatoes on your eyes?'": "Décontracté et taquin — littéralement 'tu as des tomates sur les yeux ?'",
  "Casual, to companions. Famous last words on any hike.": "Décontracté, à ses compagnons. La phrase fatidique de toute randonnée.",
  "Casual, to family/friends. Brotzeit = bread, cheese, sausage — the mandatory trail picnic, especially in the south.": "Décontracté, à la famille et aux amis. Brotzeit = pain, fromage, saucisse — le pique-nique de rando obligatoire, surtout dans le sud.",
  "Casual, to friends. The flat-rate monthly ticket for all regional transport — changed how Germans plan day trips.": "Décontracté, à des amis. L'abonnement mensuel forfaitaire pour tous les transports régionaux — il a changé la façon dont les Allemands planifient leurs excursions.",
  "Casual, to friends/partner. 'An den See fahren' is the German summer ritual — pack the Picknick.": "Décontracté, à des amis ou à son partenaire. 'An den See fahren' est le rituel estival allemand — prépare le Picknick.",
  "Casual, to one person (du) — group: Lasst uns anfangen; formal: Fangen wir an": "Décontracté, à une seule personne (du) — au groupe : Lasst uns anfangen ; formel : Fangen wir an",
  "Casual, universal. The standard excuse to step outside — nobody questions frische Luft.": "Décontracté, universel. L'excuse standard pour sortir — personne ne discute la frische Luft.",
  "Casual, wry — literally 'life is no pony farm'": "Décontracté et pince-sans-rire — littéralement 'la vie n'est pas un poney-club'",
  "casual, younger speakers; Hautpflege is the more formal word": "décontracté, plutôt chez les jeunes ; Hautpflege est le mot plus formel",
  "Casual; 'die Pause' is the break, 'der Pausenhof' the yard it happens on.": "Décontracté ; 'die Pause' est la récréation, 'der Pausenhof' la cour où elle se passe.",
  "casual; 'platt' = wiped out, works for any exhaustion": "décontracté ; 'platt' = lessivé, valable pour toute forme d'épuisement",
  "casual; 'Proteinshake' works too": "décontracté ; 'Proteinshake' fonctionne aussi",
  "casual; 'pumpen gehen' marks you as a weights person, not a treadmill person": "décontracté ; 'pumpen gehen' vous classe du côté de la fonte, pas du tapis de course",
  "casual; 'sich etwas ziehen' = to pull a muscle": "décontracté ; 'sich etwas ziehen' = se faire un claquage",
  "Casual; ackern makes the work sound tiring or relentless.": "Décontracté ; ackern fait sonner le travail comme épuisant et sans répit.",
  "Casual; adults admit it with a grin": "Décontracté ; les adultes l'avouent avec un sourire en coin",
  "casual; literally also to plough a field": "décontracté ; littéralement aussi labourer un champ",
  "casual; stechen lassen (literally 'have it pricked') is the idiomatic verb for tattoos": "décontracté ; stechen lassen (littéralement 'se faire piquer') est le verbe idiomatique pour les tatouages",
  "casual; the question everyone asks": "décontracté ; la question que tout le monde pose",
  "casual; the standard (optimistic) answer": "décontracté ; la réponse habituelle (optimiste)",
  "Casual; the way adults confess it with a grin.": "Décontracté ; la façon dont les adultes l'avouent avec un sourire.",
  "casual: kicken gehen = to go and play football": "décontracté : kicken gehen = aller jouer au foot",
  "Casual. 'Baden gehen' = swim outdoors (lake, sea); 'schwimmen gehen' leans towards the pool.": "Décontracté. 'Baden gehen' = se baigner dehors (lac, mer) ; 'schwimmen gehen' penche vers la piscine.",
  "Casual. 'Eine Runde drehen' = do a loop; works for walks, bike rides or a quick drive.": "Décontracté. 'Eine Runde drehen' = faire un tour ; vaut pour la marche, le vélo ou un petit tour en voiture.",
  "Casual. 'Sich etwas holen' = to catch/get something (sunburn, a cold).": "Décontracté. 'Sich etwas holen' = attraper quelque chose (coup de soleil, rhume).",
  "casually clipped to 'der Elfer'": "abrégé familièrement en 'der Elfer'",
  "Cheerful surrender to one good argument, not to the whole debate — said with a laugh, and very often followed by 'aber trotzdem ...'. German needs the 'erwischt': bare 'Da hast du mich' sounds unfinished. Fine with friends and colleagues; in a real row the same words come out sarcastic, so save it for when you're smiling.": "Capitulation joyeuse devant un bon argument, pas devant tout le débat — dit en riant, et très souvent suivi de 'aber trotzdem ...'. L'allemand a besoin de 'erwischt' : le simple 'Da hast du mich' sonne inachevé. Ça passe entre amis et collègues ; dans une vraie dispute, les mêmes mots sortent sarcastiques, alors gardez-les pour les moments où vous souriez.",
  "Chores": "Tâches ménagères",
  "Clean fault-owning, no hedging — respected in relationships and at work alike. The clipped 'Mein Fehler' is the casual 'my bad' for small stuff.": "Reconnaissance nette de sa faute, sans échappatoire — respectée en couple comme au travail. Le laconique 'Mein Fehler' est la version décontractée pour les broutilles.",
  "close friends only — sharing a cigarette or vape": "entre amis proches seulement — partager une cigarette ou une vapoteuse",
  "Coarse — stronger than 'das ist mir egal'. Friends only; rude if said to a teacher, boss, or official.": "Grossier — plus fort que 'das ist mir egal'. Entre amis seulement ; impoli face à un enseignant, un chef ou un fonctionnaire.",
  "Coarse and common among friends. It can sound confrontational when said angrily.": "Grossier et courant entre amis. Dit avec colère, cela peut sonner comme une provocation.",
  "Coarse and common. With a smile it can show disbelief among friends; with an angry voice it accuses someone of messing with you.": "Grossier et courant. Avec un sourire, cela exprime l'incrédulité entre amis ; d'une voix en colère, cela accuse quelqu'un de se moquer de vous.",
  "Coarse-casual — 'forget it, who cares'. Banter-safe among friends; not for formal company.": "Grossier-décontracté — 'laisse tomber, on s'en fiche'. Passe en plaisanterie entre amis ; pas en compagnie formelle.",
  "Coarse-casual — 'zum Kotzen' (enough to make you vomit) is the strong end of 'that was terrible'. Friends and family, not the office.": "Grossier-décontracté — 'zum Kotzen' (à en vomir) est l'extrémité forte de 'c'était atroce'. Amis et famille, pas le bureau.",
  "Coarse-casual — Scheiß- glues onto any noun (Scheißwetter, Scheißjob, Scheißauto). Friends and family, not the office.": "Grossier-décontracté — Scheiß- se colle à n'importe quel nom (Scheißwetter, Scheißjob, Scheißauto). Amis et famille, pas le bureau.",
  "Coarse-colloquial and strong — 'Schnauze' is an animal's snout, so this is blunt, borderline-rude frustration for partners and friends, never the office. The polite sibling is 'Ich hab die Nase voll' (nose instead of snout), safe anywhere.": "Grossier-familier et fort — 'Schnauze' est le museau d'un animal, donc c'est une frustration franche, à la limite de l'impolitesse, pour partenaires et amis, jamais pour le bureau. Le frère poli est 'Ich hab die Nase voll' (nez au lieu de museau), sans risque partout.",
  "coden is casual Denglisch; completely normal in the du-form dev crowd.": "coden est du denglisch décontracté ; tout à fait normal dans le milieu dev qui se tutoie.",
  "Colloquial (Kopfnuss = headbutt/noogie)": "Familier (Kopfnuss = coup de tête ou pichenette sur le crâne)",
  "Colloquial and openly insulting — fine among friends, rude about strangers. Milder alternatives are blöd and doof.": "Familier et ouvertement insultant — ça passe entre amis, impoli à propos d'inconnus. Les alternatives plus douces sont blöd et doof.",
  "Colloquial and strong; covers verbal and psychological cruelty, not just physical.": "Familier et fort ; couvre la cruauté verbale et psychologique, pas seulement physique.",
  "Colloquial and strong; verbal or psychological cruelty": "Familier et fort ; cruauté verbale ou psychologique",
  "colloquial and very common; 'Funkstille' is the go-to image for a communication freeze in families": "familier et très courant ; 'Funkstille' est l'image de référence pour un silence radio dans les familles",
  "colloquial anglicism (Duden-listed); marketing and social media register": "anglicisme familier (répertorié dans le Duden) ; registre du marketing et des réseaux sociaux",
  "Colloquial but harmless — safe with colleagues and family.": "Familier mais anodin — sans risque avec les collègues et la famille.",
  "Colloquial but harmless — the polite cousin of 'verarschen'. Safe with colleagues, in-laws, anyone informal.": "Familier mais anodin — le cousin poli de 'verarschen'. Sans risque avec les collègues, la belle-famille, n'importe qui en registre informel.",
  "Colloquial but serious; 'zu dritt' = three of them together.": "Familier mais grave ; 'zu dritt' = à trois.",
  "Colloquial combo of Ja + Nein": "Mot-valise familier de Ja + Nein",
  "Colloquial fixed expression meaning that someone loses their nerve or retreats. It is not sexual in this use.": "Expression figée familière signifiant que quelqu'un se dégonfle ou fait marche arrière. Rien de sexuel dans cet emploi.",
  "colloquial for lowering graphics or volume: 'die Grafik runterdrehen'. Formal 'herunterdrehen' sounds stiff in speech": "familier pour baisser les graphismes ou le volume : 'die Grafik runterdrehen'. Le formel 'herunterdrehen' sonne raide à l'oral",
  "Colloquial idiom, mild — groaning at a joke everyone has heard a hundred times. Friends and casual colleagues.": "Expression familière, douce — le grognement face à une blague entendue cent fois. Amis et collègues détendus.",
  "colloquial intensifier: mächtig stolz = mighty proud": "intensificateur familier : mächtig stolz = drôlement fier",
  "Colloquial northern greeting — standard from Hamburg to the Danish border, at any hour of the day, and it will mark you out anywhere south of it.": "Salutation familière du Nord — standard de Hambourg à la frontière danoise, à toute heure de la journée, et elle vous fera remarquer partout plus au sud.",
  "Colloquial sarcasm, mild-moderate — mock admiration for a mess or fiasco. Friends and casual colleagues; literally 'really big cinema'.": "Sarcasme familier, doux à modéré — admiration feinte pour un désastre ou un fiasco. Amis et collègues détendus ; littéralement 'du très grand cinéma'.",
  "Colloquial short form of herauskommen; also used of films, products or models being released.": "Forme courte familière de herauskommen ; s'emploie aussi pour la sortie de films, produits ou modèles.",
  "Colloquial shortcut": "Raccourci familier",
  "Colloquial southern greeting, and one of the few that works at both ends of a conversation. In the north it reads as visiting.": "Salutation familière du Sud, et l'une des rares qui fonctionne aux deux bouts d'une conversation. Dans le nord, elle sonne comme une visite.",
  "Colloquial, mild — casual settings with friends, family, relaxed colleagues. Often typed in chats too.": "Familier, doux — en contexte décontracté avec amis, famille, collègues détendus. Souvent tapé dans les chats aussi.",
  "Colloquial, mild — gasped mid-laughter or typed in chats. Friends, family, relaxed colleagues.": "Familier, doux — lâché en plein rire ou tapé dans un chat. Amis, famille, collègues détendus.",
  "Colloquial, mild — genuine ('der Brüller' = a roar of laughter) or ironic for something boring. Friends and casual settings.": "Familier, doux — sincère ('der Brüller' = un éclat de rire) ou ironique pour quelque chose d'ennuyeux. Amis et contextes décontractés.",
  "Colloquial, mild — telling anyone informally how funny something was. sich kaputtlachen = laugh yourself 'broken'.": "Familier, doux — pour dire à n'importe qui, en registre informel, à quel point c'était drôle. sich kaputtlachen = rire jusqu'à en être 'cassé', mourir de rire.",
  "Colloquial, rueful — literal at the casino, figurative for blowing a lead or chance. 'der Gewinn' (winnings) and 'der Verlust' (loss) are the accounting pair that goes with it.": "Familier, plein de regret — littéral au casino, figuré quand on gâche une avance ou une occasion. 'der Gewinn' (les gains) et 'der Verlust' (la perte) sont la paire comptable qui l'accompagne.",
  "colloquial, what children do in sand; graben is neutral": "familier, ce que les enfants font dans le sable ; graben est neutre",
  "Colloquial; 'sich prügeln' is physical, much stronger than 'sich streiten'.": "Familier ; 'sich prügeln' est physique, bien plus fort que 'sich streiten'.",
  "colloquial; invariable: ein super Film": "familier ; invariable : ein super Film",
  "colloquially also snappy, punchy (UI, prose, deadlines)": "familièrement aussi vif, percutant (interfaces, textes, délais)",
  "colloquially shortened to 'das Gespräch'": "abrégé familièrement en 'das Gespräch'",
  "Colloquially, Der Hammer! means amazing or awesome — the literal tool is the primary card meaning.": "Familièrement, Der Hammer! veut dire génial — mais le sens premier de la carte est l'outil.",
  "common and informal; can describe a person, idea or situation": "courant et informel ; peut décrire une personne, une idée ou une situation",
  "Common complaint": "Plainte courante",
  "Common slang reaction": "Réaction courante en argot",
  "Common slang reaction to bad news — mies = lousy, shabby": "Réaction argotique courante à une mauvaise nouvelle — mies = nul, minable",
  "Comprehension note for adult informal German. The neutral anatomy word is 'Penis'; 'Schwanz' has roughly the force of English 'dick'.": "Note de compréhension pour l'allemand informel entre adultes. Le mot anatomique neutre est 'Penis' ; 'Schwanz' a à peu près la force de l'anglais 'dick'.",
  "Confirming": "Confirmer",
  "Confrontational warning after being insulted — it escalates, not calms. Understand it as 'you're one word away from real trouble'.": "Avertissement de confrontation après une insulte — il envenime, il n'apaise pas. À comprendre comme 'tu es à un mot des vrais ennuis'.",
  "Consent": "Consentement",
  "Consent — always check": "Consentement — toujours demander",
  "Conversational geopolitics with an opinion baked in — fine among friends, spicier at work": "Géopolitique de conversation, avec une opinion incluse — ça passe entre amis, plus délicat au travail",
  "Core repair line after words that cut too deep — tender, serious, for partners, family, close friends. Follow it with what you DID mean, or it hangs in the air.": "La phrase de réparation essentielle après des mots qui ont coupé trop profond — tendre, sérieuse, pour partenaires, famille, amis proches. Enchaînez avec ce que vous vouliez VRAIMENT dire, sinon elle reste en suspens.",
  "Crude but affectionate — literally 'throw up on you'. Close friends only, never a colleague you don't know well. The tearful version is 'sich bei jemandem ausheulen'.": "Cru mais affectueux — littéralement 'vomir sur quelqu'un'. Amis proches seulement, jamais un collègue que vous connaissez peu. La version larmoyante est 'sich bei jemandem ausheulen'.",
  "Crude for people (fine among friends, marks heavy drinking); for animals it is simply the neutral word for 'to drink'.": "Cru pour les humains (ça passe entre amis, cela dénote une forte consommation) ; pour les animaux, c'est simplement le mot neutre pour boire.",
  "Crude-ish colloquial, from saufen. Fine among friends, carries a judgy or comic undertone; not for formal settings.": "Langue familière plutôt crue, venue de saufen. Ça passe entre amis, avec un sous-entendu moralisateur ou comique ; pas pour un cadre formel.",
  "Crude-ish colloquial, mildly judgy or comic — friends and family only. The neutral word for reports and polite company is 'betrunken'.": "Langue familière plutôt crue, un peu moralisatrice ou comique — amis et famille seulement. Le mot neutre pour les rapports et la compagnie polie est 'betrunken'.",
  "Crude, self-deprecating — friends only. 'saufen' always signals heavy drinking; never use it about someone in a serious context.": "Cru, autodérisoire — entre amis seulement. 'saufen' signale toujours une forte consommation ; ne l'employez jamais à propos de quelqu'un dans un contexte sérieux.",
  "dark humour among friends; 'Echsenmenschen' is the go-to absurd-conspiracy reference": "humour noir entre amis ; 'Echsenmenschen' est la référence type aux complots absurdes",
  "das Band — the conveyor. Braking on it is the one real mistake to avoid.": "das Band — le tapis roulant. Freiner dessus est la seule vraie erreur à éviter.",
  "das Bügeleisen — the iron. The warning every household repeats.": "das Bügeleisen — le fer à repasser. L'avertissement que répète chaque foyer.",
  "das Halbjahreszeugnis — the February report. The early warning system.": "das Halbjahreszeugnis — le bulletin de février. Le système d'alerte précoce.",
  "Das hängt davon ab = it depends. Casually, mit Freunden abhängen = to hang out.": "Das hängt davon ab = ça dépend. De façon décontractée, mit Freunden abhängen = traîner avec des amis.",
  "das Profil — the tread. 'ist runter' — worn away; casual passive Germany runs on.": "das Profil — la sculpture du pneu. 'ist runter' — usée ; le passif décontracté sur lequel roule l'Allemagne.",
  "das Rücklicht — the rear light. 'nur noch schwach' — the warning phase before darkness.": "das Rücklicht — le feu arrière. 'nur noch schwach' — la phase d'avertissement avant le noir complet.",
  "das Spritgeld — the fuel share. Simple beats fair-to-the-cent; friendships prefer round numbers.": "das Spritgeld — la participation à l'essence. Simple vaut mieux que juste au centime ; l'amitié préfère les chiffres ronds.",
  "das Teil — the casual word for any piece of clothing. The rule that prevents the pink wash.": "das Teil — le mot décontracté pour n'importe quel vêtement. La règle qui évite la lessive rose.",
  "das Wartezimmer — from the doctor pack, considerably louder. Cats sit high; dogs make friends.": "das Wartezimmer — venu du lot sur le médecin, nettement plus bruyant. Les chats sont perchés ; les chiens se font des amis.",
  "Dating": "Rencontres",
  "Dative again: 'mir ist übel', never 'ich bin übel'. Watch the double life of the word — under-25s use bare 'übel' as slang for insane/awesome ('übel gut'), but 'Mir ist übel' only ever means nausea.": "Encore le datif : 'mir ist übel', jamais 'ich bin übel'. Attention à la double vie du mot — les moins de 25 ans emploient 'übel' seul comme argot pour 'dingue, génial' ('übel gut'), mais 'Mir ist übel' ne veut jamais dire que la nausée.",
  "Deadpan irony, mild — the standard flat response when someone teases you. Safe with anyone informal; can sound genuinely annoyed if said sharply.": "Ironie pince-sans-rire, douce — la réponse plate standard quand on vous taquine. Sans risque avec n'importe qui en registre informel ; dit sèchement, cela peut sonner vraiment agacé.",
  "Deadpan sarcasm, mild — the everyday ironic groan at bad news. Universal: friends, family, muttered at work.": "Sarcasme pince-sans-rire, doux — le grognement ironique quotidien face à une mauvaise nouvelle. Universel : amis, famille, marmonné au travail.",
  "Deliberately vague — it lets both sides keep it casual. 'was' here is short for 'etwas'.": "Volontairement vague — cela permet aux deux parties de rester décontractées. 'was' est ici l'abrégé de 'etwas'.",
  "Denglish gym slang, completely standard between lifters; more formal: 'Kannst du mir Hilfestellung geben?'": "Argot de salle en denglisch, tout à fait standard entre pratiquants ; plus formel : 'Kannst du mir Hilfestellung geben?'",
  "der Aszendent — the follow-up question that separates casual from committed.": "der Aszendent — la question de relance qui sépare les curieux des convaincus.",
  "der Blitzer = speed camera (colloquial); note: radar-warning apps are illegal to use while driving in Germany (§ 23 StVO)": "der Blitzer = radar (familier) ; à noter : les applis d'avertissement de radars sont interdites au volant en Allemagne (§ 23 StVO)",
  "der Helferkreis — the informal volunteer group, common in refugee and neighbourhood support.": "der Helferkreis — le groupe de bénévoles informel, courant dans l'aide aux réfugiés et l'entraide de quartier.",
  "der Platten — the flat tyre, colloquial and universal. The commute's classic opening line.": "der Platten — la crevaison, familier et universel. La réplique d'ouverture classique des trajets quotidiens.",
  "der Strafzettel, colloquially das Knöllchen = parking ticket": "der Strafzettel, familièrement das Knöllchen = contravention de stationnement",
  "Desire": "Envie",
  "die Abmahnung — the warning shot, at work or over copyright. Serious, not final.": "die Abmahnung — le coup de semonce, au travail ou en matière de droit d'auteur. Sérieux, mais pas définitif.",
  "die Abmahnung — the written warning. Serious, but far from a dismissal.": "die Abmahnung — l'avertissement écrit. Sérieux, mais loin d'un licenciement.",
  "die Bescherung = the ritual gift-opening moment on Heiligabend; every family defends its own timing (before church, after dinner, after the carols). Warning: 'Da haben wir die Bescherung!' as an exclamation ironically means 'now we're in a fine mess'.": "die Bescherung = le moment rituel de l'ouverture des cadeaux le soir du 24 ; chaque famille défend son propre horaire (avant la messe, après le dîner, après les chants). Attention : 'Da haben wir die Bescherung!' en exclamation signifie ironiquement 'nous voilà dans de beaux draps'.",
  "die DM, pronounced 'deh-em'; 'ne' = clipped 'eine'. Neutral-casual — the full German 'private Nachricht' sounds oddly formal now.": "die DM, prononcé 'dé-em' ; 'ne' = 'eine' abrégé. Neutre-décontracté — le complet 'private Nachricht' sonne aujourd'hui étrangement formel.",
  "die Hausnummer — colloquial for a rough figure. More with a role change.": "die Hausnummer — familier pour un ordre de grandeur. Davantage si le poste change.",
  "die Jugendfeuerwehr — where most volunteers begin. Knots, hoses and friendships.": "die Jugendfeuerwehr — là où commencent la plupart des volontaires. Des nœuds, des tuyaux et des amitiés.",
  "die Kantine — the subsidised lunch. The invitation that builds actual friendships.": "die Kantine — le déjeuner subventionné. L'invitation qui crée de vraies amitiés.",
  "die Laune = mood. Owning the mood stops it becoming a fight. Colloquial synonym: 'Ich bin schlecht drauf.' Opposite: gute Laune / gut drauf.": "die Laune = l'humeur. Assumer son humeur l'empêche de tourner à la dispute. Synonyme familier : 'Ich bin schlecht drauf.' Contraire : gute Laune / gut drauf.",
  "die Lawine — the avalanche. The warning is not decorative.": "die Lawine — l'avalanche. L'avertissement n'est pas décoratif.",
  "die Leitung = the phone line (also the cable from your ISP, and 'eine lange Leitung haben' = to be slow on the uptake). Hanging up and redialling is the universal German fix — announcing it first stops the other person thinking you hung up on them. 'mies' is casual for lousy.": "die Leitung = la ligne téléphonique (aussi le câble du fournisseur, et 'eine lange Leitung haben' = être lent à la détente). Raccrocher et rappeler est la solution universelle en Allemagne — l'annoncer d'abord évite que l'autre croie que vous lui avez raccroché au nez. 'mies' est le mot décontracté pour minable.",
  "Direct and neutral: 'Ich bin schwanger.' Colloquially, 'schwanger von ihm' names the father.": "Direct et neutre : 'Ich bin schwanger.' Familièrement, 'schwanger von ihm' nomme le père.",
  "draufgehen (colloquial) = gets eaten up; die Abgaben = social contributions on top of taxes; casual complaining": "draufgehen (familier) = y passer, être englouti ; die Abgaben = les cotisations sociales en plus des impôts ; plainte décontractée",
  "drohen with a thing as subject = to loom/threaten to occur: Dehydrierung droht. sonst carries the warning.": "drohen avec une chose comme sujet = menacer de survenir : Dehydrierung droht. sonst porte l'avertissement.",
  "Du form, between friends. French speakers in Germany keep the word 'Bürgeramt'. Appointments are notoriously scarce in big cities — book the moment you know you're moving.": "Forme en du, entre amis. Les francophones en Allemagne gardent le mot 'Bürgeramt'. Les rendez-vous sont notoirement rares dans les grandes villes — réservez dès que vous savez que vous déménagez.",
  "du-form for friends and partners. With strangers or officials: 'Können Sie das bitte wiederholen?'": "Forme en du pour les amis et les partenaires. Avec des inconnus ou des fonctionnaires : 'Können Sie das bitte wiederholen?'",
  "Du-form, friends and family. 'gerade' (usually swallowed to 'grad') carries the 'right now' — leave it out and you sound like you're asking whether they are physically capable of speech.": "Forme en du, amis et famille. 'gerade' (souvent avalé en 'grad') porte le 'là, maintenant' — sans lui, on dirait que vous demandez si la personne est physiquement capable de parler.",
  "düngen = to fertilize; der Dünger = fertilizer. Du register — said between family/friends": "düngen = fertiliser ; der Dünger = l'engrais. Registre du du — entre famille et amis",
  "eh = anyway / in any case (colloquial 'ohnehin')": "eh = de toute façon / en tout cas (familier pour 'ohnehin')",
  "eine Runde schmeißen — literally throwing a round. Casual, generous, slightly theatrical.": "eine Runde schmeißen — littéralement lancer une tournée. Décontracté, généreux, un peu théâtral.",
  "Emergency": "Urgence",
  "Emphasis": "Insistance",
  "Emphatic casual yes": "Oui décontracté et appuyé",
  "Encouragement between friends or from a partner — the compliment learners most want to hear.": "Encouragement entre amis ou de la part d'un partenaire — le compliment que les apprenants rêvent d'entendre.",
  "Enemy info": "Info ennemi",
  "English loan, fully naturalized and plural; 'doch' makes it dismissive — casual register": "emprunt à l'anglais, pleinement naturalisé et au pluriel ; 'doch' le rend dédaigneux — registre décontracté",
  "Enthusiastic yes": "Oui enthousiaste",
  "Erwischen = catching red-handed, in the act or via messages. The hinge word of every cheating story — expect friends to ask 'Wie hast du's rausgefunden?'": "Erwischen = prendre sur le fait, en direct ou par messages. Le mot pivot de toute histoire d'infidélité — attendez-vous à ce que les amis demandent : 'Wie hast du's rausgefunden?'",
  "Essential": "Essentiel",
  "everyday casual word; also means the stubbed-out butt": "mot décontracté du quotidien ; désigne aussi le mégot écrasé",
  "Everyday colloquial spelling of nichts": "Orthographe familière courante de nichts",
  "Everyday connection method (slang 'schreib mir')": "Moyen de rester en contact au quotidien (argot 'schreib mir')",
  "Everyday criticism, medium weight; fine in casual talk about colleagues or exes.": "Critique du quotidien, de poids moyen ; ça passe dans une conversation décontractée sur des collègues ou des ex.",
  "Everyday office and friend request; rüberschicken (send over) is the casual variant.": "Demande quotidienne au bureau et entre amis ; rüberschicken (faire passer) est la variante décontractée.",
  "Everyday slang (Bock haben)": "Argot du quotidien (Bock haben)",
  "Everyday slang (spendieren = to treat)": "Argot du quotidien (spendieren = offrir, payer sa tournée)",
  "Excited announcement to friends and family. Once the context is clear, everyone just says 'Gespräch'.": "Annonce enthousiaste aux amis et à la famille. Une fois le contexte clair, tout le monde dit simplement 'Gespräch'.",
  "Extremely common in speech as a hedge: Das ist quasi dasselbe. Latin by origin, fully casual in use.": "Extrêmement courant à l'oral comme atténuateur : Das ist quasi dasselbe. D'origine latine, tout à fait décontracté à l'usage.",
  "Facharzt = specialist; colloquially also \"einen Termin ausmachen\"": "Facharzt = médecin spécialiste ; familièrement aussi 'einen Termin ausmachen'",
  "Falschparken = illegal/incorrect parking": "Falschparken = stationnement illicite ou mal fait",
  "False friend warning: this is only appointment in the sense of naming someone to a position (die Ernennung zum Professor). A diary appointment is der Termin.": "Attention faux ami : il ne s'agit que de la nomination à un poste (die Ernennung zum Professor). Un rendez-vous dans l'agenda, c'est der Termin.",
  "Family": "Famille",
  "Famous last words — friends will quote it back at you for months.": "Phrase fatidique — tes amis te la ressortiront pendant des mois.",
  "Farewell": "Au revoir",
  "Feeling": "Sentiment",
  "feiern = to celebrate, colloquially 'to love something'; very current usage.": "feiern = faire la fête, familièrement 'adorer quelque chose' ; usage très actuel.",
  "fett = huge (colloquial intensifier); standard dev talk, not rude.": "fett = énorme (intensificateur familier) ; jargon dev courant, pas grossier.",
  "Finding help": "Trouver de l'aide",
  "firm but civil pushback; the 'doch längst' signals mild exasperation — fine with family, friends, colleagues": "réplique ferme mais courtoise ; le 'doch längst' signale une légère exaspération — ça passe en famille, entre amis, avec des collègues",
  "Fixed casual set expression; already short, so no further clipping.": "Expression figée décontractée ; déjà courte, donc pas d'abréviation supplémentaire.",
  "flach and steil around dahinter — the swimming-pool warning as a geometry lesson.": "flach et steil autour de dahinter — l'avertissement de la piscine sous forme de leçon de géométrie.",
  "Flight status update": "Statut du vol",
  "Flirting": "Draguer",
  "For dressing yourself up, say 'Ich verkleide mich als Pirat'. The casual question is 'Als was gehst du?' = what are you going as? 'das Kostüm' = the costume. At Rhineland Karneval, no costume marks you as a tourist or a grump.": "Pour vous déguiser vous-même, dites 'Ich verkleide mich als Pirat'. La question décontractée est 'Als was gehst du?' = en quoi tu te déguises ? 'das Kostüm' = le déguisement. Au carnaval rhénan, ne pas être déguisé vous désigne comme touriste ou rabat-joie.",
  "For getting yourself ready, say 'sich zurechtmachen': 'Ich mache mich zurecht.' The casual spoken version is 'sich fertig machen'.": "Pour vous apprêter, employez 'sich zurechtmachen' : 'Ich mache mich zurecht.' La version orale décontractée est 'sich fertig machen'.",
  "For people who have your number saved and know your voice — partner, family, close friends. 'bin's' = 'bin es'; the full 'Ich bin es' sounds oddly stiff out loud.": "Pour les gens qui ont votre numéro enregistré et reconnaissent votre voix — partenaire, famille, amis proches. 'bin's' = 'bin es' ; le complet 'Ich bin es' sonne étrangement raide à voix haute.",
  "Formal": "Formel",
  "FORMAL — Sie-form, for a receptionist, a landlord, a client. With 'passen' the day itself is the subject ('Dienstag passt mir'), so you say 'Passt Ihnen Dienstag?', never 'Passt es Ihnen am Dienstag'. The verb is the same everyday 'passen' you use with friends; only the pronoun goes up a level.": "FORMEL — forme en Sie, pour un accueil, un propriétaire, un client. Avec 'passen', c'est le jour lui-même qui est sujet ('Dienstag passt mir'), on dit donc 'Passt Ihnen Dienstag?', jamais 'Passt es Ihnen am Dienstag'. Le verbe est le même 'passen' quotidien qu'entre amis ; seul le pronom monte d'un cran.",
  "FORMAL — the closing line of every delay announcement, ever. Between friends it's a joke: deliver any bad news, then add 'Wir bitten um Ihr Verständnis' with a straight face and the Bahn reference lands instantly.": "FORMEL — la phrase de clôture de toute annonce de retard, toujours. Entre amis, c'est une blague : annoncez n'importe quelle mauvaise nouvelle, ajoutez 'Wir bitten um Ihr Verständnis' sans sourciller, et la référence à la Bahn fait mouche immédiatement.",
  "FORMAL — your last warning on the platform. 'selbsttätig' is a wonderfully stiff old word for 'automatically' that has survived almost nowhere outside railway announcements.": "FORMEL — votre dernier avertissement sur le quai. 'selbsttätig' est un vieux mot merveilleusement guindé pour 'automatiquement', qui n'a presque survécu nulle part hors des annonces ferroviaires.",
  "Friendly disbelief between friends — 'den' stands for der Film or der Song. Delivered flat and without a grin it reads as contempt, so keep the eyebrows involved.": "Incrédulité amicale entre amis — 'den' renvoie à der Film ou der Song. Dit à plat et sans sourire, cela passe pour du mépris ; faites donc participer les sourcils.",
  "Friends commonly drop 'Das' and the final e in 'finde'. The full form remains correct and is useful in careful speech.": "Entre amis, on laisse souvent tomber 'Das' et le -e de 'finde'. La forme complète reste correcte et sert dans un discours soigné.",
  "Frustrated, to friends. 'schon wieder' carries the job-hunt fatigue.": "Agacé, entre amis. 'schon wieder' porte toute la lassitude de la recherche d'emploi.",
  "geblitzt werden = to get caught by a speed camera — the standard colloquial verb for it": "geblitzt werden = se faire flasher par un radar — le verbe familier standard pour cela",
  "Gen-Z": "Gen Z",
  "Genuine compliment between friends; on a date it's practically flirting.": "Vrai compliment entre amis ; lors d'un rendez-vous, c'est pratiquement du flirt.",
  "Genuine distress, not everyday tiredness — this is a step past 'Ich bin total fertig' and friends will hear it as a real signal.": "Une vraie détresse, pas la fatigue ordinaire — c'est un cran au-dessus de 'Ich bin total fertig', et les amis l'entendent comme un signal réel.",
  "gereizt — irritable, like a nerve already touched. Fair warning to the room.": "gereizt — à cran, comme un nerf déjà touché. Un avertissement loyal à toute la pièce.",
  "German friends genuinely text each other their IBAN — it isn't treated as sensitive the way a card number is. Payment apps exist, but the plain bank transfer is still the default between adults.": "Les amis allemands s'envoient réellement leur IBAN par message — il n'est pas traité comme aussi sensible qu'un numéro de carte. Les applis de paiement existent, mais le simple virement bancaire reste la norme entre adultes.",
  "German has no word for 'playdate' — 'zum Spielen kommen' is how you actually arrange one. The 'mal' keeps it casual and easy to decline, which is exactly the point.": "L'allemand n'a pas de mot pour 'playdate' — 'zum Spielen kommen' est la façon dont on en organise un. Le 'mal' garde la chose décontractée et facile à décliner, et c'est précisément le but.",
  "German has three words for 'you': du to one friend, ihr to several friends, Sie to a stranger. The same question is Woher kommst du? and Woher kommen Sie?": "L'allemand a trois mots pour 'tu/vous' : du à un ami, ihr à plusieurs amis, Sie à un inconnu. La même question donne Woher kommst du? et Woher kommen Sie?",
  "gib — du-imperative of geben with vowel change; mal keeps it casual, not bossy.": "gib — impératif en du de geben avec alternance vocalique ; mal garde le ton décontracté, pas autoritaire.",
  "Greeting": "Salutation",
  "Grufti = colloquial for goth (from Gruft = tomb/crypt)": "Grufti = familier pour gothique (de Gruft = caveau, crypte)",
  "Gunsmith": "Armurier",
  "Half-joking household rule for the unsortable. Colloquial, said with a shrug.": "Règle domestique à moitié pour rire, pour tout ce qui ne se trie pas. Familier, dit avec un haussement d'épaules.",
  "half-joking quitter's line; 'ich schwör' is casual spoken German": "réplique à moitié sérieuse de celui qui abandonne ; 'ich schwör' est de l'allemand parlé décontracté",
  "Half-joking threat when someone won't stop talking. Among friends it's banter; from a moderator it's a real sanction.": "Menace à moitié pour rire quand quelqu'un ne s'arrête pas de parler. Entre amis, c'est une vanne ; venant d'un modérateur, c'est une vraie sanction.",
  "happig = steep/hefty (colloquial). German utilities charge a monthly Abschlag (installment); the annual Abrechnung can bring a painful Nachzahlung (back payment)": "happig = salé, costaud (familier). Les fournisseurs allemands prélèvent un Abschlag mensuel (acompte) ; le décompte annuel (Abrechnung) peut amener un douloureux Nachzahlung (rappel à payer)",
  "Heated disbelief — loud but not vulgar, extremely common. Fine among partners and friends; in a real fight it reads as 'you've lost your mind'.": "Incrédulité échauffée — fort mais pas vulgaire, extrêmement courant. Ça passe en couple et entre amis ; dans une vraie dispute, cela signifie 'tu as perdu la tête'.",
  "hol mal = casual imperative; note 'das Licht geht nicht' would mean the lamp itself is broken, not a power cut": "hol mal = impératif décontracté ; attention, 'das Licht geht nicht' voudrait dire que la lampe elle-même est cassée, pas qu'il y a une coupure",
  "Hopeful repair language. 'Hinkriegen' is colloquial and warm — much more natural than 'reparieren'.": "Langage de réparation plein d'espoir. 'Hinkriegen' est familier et chaleureux — bien plus naturel que 'reparieren'.",
  "How Germans sell a friend before you meet them. Note the future: 'den wirst du bestimmt mögen' — present 'den magst du' would claim you already like someone you've never met. 'witzig' is for a person's sense of humour; 'lustig' leans towards situations and things. The demonstratives 'der/den' instead of 'er/ihn' are standard casual speech about people.": "C'est ainsi que les Allemands vous vendent un ami avant la rencontre. Notez le futur : 'den wirst du bestimmt mögen' — le présent 'den magst du' affirmerait que vous appréciez déjà quelqu'un que vous n'avez jamais vu. 'witzig' concerne l'humour d'une personne ; 'lustig' penche vers les situations et les choses. Les démonstratifs 'der/den' au lieu de 'er/ihn' sont la norme à l'oral décontracté à propos des gens.",
  "How Meinungsfreiheit shows up in casual talk. Note: this phrase carries political colouring for some listeners — use with awareness.": "Comment la Meinungsfreiheit apparaît dans la conversation ordinaire. Attention : cette formule a une couleur politique pour certains auditeurs — à employer en connaissance de cause.",
  "How you confess a current obsession. 'Auf Dauerschleife' = on endless loop; casual, very common.": "Comment on avoue une obsession du moment. 'Auf Dauerschleife' = en boucle infinie ; décontracté, très courant.",
  "How you point a friend towards a doctor or a Beratungsstelle without dropping them. A male speaker says 'der Falsche'. Note the colloquial split of 'dafür' into 'da ... für', which is what people actually say.": "Comment orienter un ami vers un médecin ou une Beratungsstelle sans le laisser tomber. Un locuteur masculin dit 'der Falsche'. Notez la séparation familière de 'dafür' en 'da ... für' — c'est ainsi qu'on parle réellement.",
  "HUFFY / JOKING between partners and friends — mock silent treatment after you ate the last slice or spoiled the ending. The pout IS the punchline. Said flat and cold in a real fight it turns childish and genuinely wounding, so the grin is not optional.": "BOUDEUR / POUR RIRE entre partenaires et amis — silence punitif simulé après que vous avez mangé la dernière part ou dévoilé la fin. La moue EST la chute. Dit à plat et froidement dans une vraie dispute, cela devient puéril et réellement blessant : le sourire n'est pas facultatif.",
  "HURTFUL — the classic 'immer/nie' generalisation that every couples therapist warns about. You'll hear it a lot; recognise it as venting, and avoid saying it yourself: swap 'immer' for 'heute' and it becomes fair.": "BLESSANT — la généralisation classique en 'immer/nie' contre laquelle tout thérapeute de couple met en garde. Vous l'entendrez souvent ; reconnaissez-la comme une décharge, et évitez de la dire vous-même : remplacez 'immer' par 'heute' et elle devient juste.",
  "Hyperbole among friends about shocking behaviour. Psychopath and Soziopath are heavy armchair diagnoses — clearly banter or clearly serious, nothing in between.": "Hyperbole entre amis à propos d'un comportement choquant. Psychopath et Soziopath sont de lourds diagnostics de comptoir — clairement de la vanne ou clairement du sérieux, rien entre les deux.",
  "idiomatic, informal": "idiomatique, informel",
  "Im Alter von 30 = at the age of 30. As an exclamation, Alter! = dude! — very casual.": "Im Alter von 30 = à l'âge de 30 ans. En exclamation, Alter! = mec ! — très décontracté.",
  "in casual speech often shortened to was: Hast du was gehört?": "à l'oral décontracté, souvent abrégé en was : Hast du was gehört?",
  "In Discord contexts everyone says 'der Channel'; the German 'Kanal' survives for YouTube channels, oddly enough. Casual imperative with softening 'mal'.": "Dans le contexte Discord, tout le monde dit 'der Channel' ; le 'Kanal' allemand survit curieusement pour les chaînes YouTube. Impératif décontracté avec un 'mal' adoucissant.",
  "In the moment": "Sur le moment",
  "Informal": "Informel",
  "Informal — friends only": "Informel — entre amis seulement",
  "Informal — the spoken contraction you'll usually hear": "Informel — la contraction orale qu'on entend le plus souvent",
  "Informal — to strangers or staff say: Sprechen Sie Englisch?": "Informel — à des inconnus ou au personnel, dites : Sprechen Sie Englisch?",
  "Informal and rude: jemandem den Stinkefinger zeigen.": "Informel et grossier : jemandem den Stinkefinger zeigen.",
  "Informal and uncountable: Nimm dein Zeug mit. It is also the tail of many compounds -- Werkzeug, Fahrzeug, Flugzeug.": "Informel et indénombrable : Nimm dein Zeug mit. C'est aussi la queue de nombreux composés — Werkzeug, Fahrzeug, Flugzeug.",
  "Informal and warm, mostly southern. 'Grüß Gott' is its formal, Bavarian and Austrian cousin.": "Informel et chaleureux, surtout dans le sud. 'Grüß Gott' en est le cousin formel, bavarois et autrichien.",
  "Informal imperative among friends at a party or in the car. The 'mal' softens the command. Opposite: 'Mach mal leiser!'": "Impératif informel entre amis en soirée ou en voiture. Le 'mal' adoucit l'ordre. Contraire : 'Mach mal leiser!'",
  "Informal imperative of separable 'ablehnen' is 'Lehn ... ab'; after 'wenn', 'kennst' goes to the end.": "L'impératif informel du séparable 'ablehnen' est 'Lehn ... ab' ; après 'wenn', 'kennst' passe à la fin.",
  "Informal imperative of separable 'aufheben': 'Heb ... auf'; the full written form is 'Hebe'.": "Impératif informel du séparable 'aufheben' : 'Heb ... auf' ; la forme écrite complète est 'Hebe'.",
  "informal loan from English; das Okay – the go-ahead": "emprunt informel à l'anglais ; das Okay – le feu vert",
  "Informal reply — with Sie say: Und Ihnen?": "Réponse informelle — avec Sie, on dit : Und Ihnen?",
  "Informal term for a friend": "Terme informel pour un ami",
  "informal, e.g. eine brenzlige Situation": "informel, p. ex. eine brenzlige Situation",
  "informal; the standard German way to say someone drifted off into conspiracy land": "informel ; la manière allemande standard de dire que quelqu'un a dérivé vers les complots",
  "Informal. 'dir' adds the idea of wishing for something for yourself and is the usual form here: 'Was wünschst du dir ...?' Formal version: Was wünschen Sie sich zum Geburtstag?": "Informel. 'dir' ajoute l'idée de souhaiter quelque chose pour soi et c'est la forme habituelle ici : 'Was wünschst du dir ...?' Version formelle : Was wünschen Sie sich zum Geburtstag?",
  "Introducing": "Se présenter",
  "Ironic pub humour — twists the serious slogan 'Alkohol ist keine Lösung'. Friends only; know that it IS a joke before deploying it.": "Humour de bistrot ironique — il détourne le slogan sérieux 'Alkohol ist keine Lösung'. Entre amis seulement ; sachez que c'EST une blague avant de la sortir.",
  "Jokey, internet-flavoured pet-parent talk among friends. Self-aware and affectionate – don't use it at the vet's front desk.": "Parler de 'parent d'animal', blagueur et teinté d'internet, entre amis. Autodérisoire et affectueux — à éviter à l'accueil du vétérinaire.",
  "JOKING but pointed — half confession, half comment on the length. WhatsApp's speed button is a genuine fixture of German friendships. Note the collocation 'in doppelter Geschwindigkeit' (not 'auf'); casually you'd just say 'auf 2x'. The answer you'll get: 'Dann red ich eben schneller.'": "POUR RIRE mais bien senti — mi-aveu, mi-commentaire sur la longueur. Le bouton de vitesse de WhatsApp est un vrai pilier des amitiés allemandes. Notez la collocation 'in doppelter Geschwindigkeit' (pas 'auf') ; à l'oral décontracté, on dit simplement 'auf 2x'. La réponse que vous obtiendrez : 'Dann red ich eben schneller.'",
  "JOKING-ACCUSING between friends; die blauen Haken (blue ticks) count as evidence. The 'doch' is what makes it teasing rather than cold. Genuinely annoyed, a German would say less, not more: just 'Du hast nicht geantwortet.'": "ACCUSATION POUR RIRE entre amis ; die blauen Haken (les coches bleues) font office de preuve. C'est le 'doch' qui rend la chose taquine plutôt que froide. Vraiment agacé, un Allemand en dirait moins, pas plus : juste 'Du hast nicht geantwortet.'",
  "justifying one more — works for cigarettes and beers alike; very casual": "pour justifier la suivante — vaut aussi bien pour les cigarettes que pour les bières ; très décontracté",
  "kicken — casual football. der Bolzplatz — the scuffed pitch every neighbourhood has.": "kicken — le foot décontracté. der Bolzplatz — le terrain pelé que possède chaque quartier.",
  "kippen used transitively = to topple/overturn — colloquial force inside legal talk, which is exactly how lawyers speak.": "kippen employé transitivement = faire tomber, casser — une force familière au cœur du langage juridique, et c'est exactement ainsi que parlent les avocats.",
  "klamm — damp, and colloquially short of cash. Honest without being dramatic.": "klamm — humide, et familièrement à court d'argent. Honnête sans être dramatique.",
  "klingen — sounding. The honest warning given to every violin household's neighbours.": "klingen — sonner. L'avertissement honnête adressé aux voisins de toute maison à violon.",
  "knapp bei Kasse — tight at the till. The honest sentence that friends answer with einladen.": "knapp bei Kasse — à court à la caisse. La phrase honnête à laquelle les amis répondent par einladen.",
  "knapp bei Kasse sein = to be short of money; casual register, said among friends and family": "knapp bei Kasse sein = être à court d'argent ; registre décontracté, entre amis et en famille",
  "Knast = colloquial for jail/prison": "Knast = familier pour prison, taule",
  "Komm doch mal vorbei! — the casual open invitation.": "Komm doch mal vorbei! — l'invitation ouverte et décontractée.",
  "kopieren und einfügen is the standard wording, but casual speech happily verbs the loan — 'einfach copy-pasten' — especially among younger people; Strg+C, Strg+V is the shared shorthand.": "kopieren und einfügen est la formulation standard, mais l'oral décontracté verbalise volontiers l'emprunt — 'einfach copy-pasten' — surtout chez les jeunes ; Strg+C, Strg+V est le raccourci partagé.",
  "Krankmeldung (colloquial) is what people say; the official document is the Krankschreibung / AU-Bescheinigung": "Krankmeldung (familier) est ce que les gens disent ; le document officiel s'appelle Krankschreibung ou AU-Bescheinigung",
  "Ladder level 2, MEDIUM-MILD — like 'damn'. Fine among adults and colleagues you know; avoid in formal or religious settings.": "Niveau 2 de l'échelle, MOYEN-DOUX — comme 'bon sang'. Ça passe entre adultes et avec des collègues qu'on connaît ; à éviter en contexte formel ou religieux.",
  "Ladder level 3, MEDIUM — the most-heard German swear word, roughly like 'shit' but even more common and slightly less taboo. Fine among friends; avoid with clients, bosses you don't know, or in formal settings.": "Niveau 3 de l'échelle, MOYEN — le juron allemand le plus entendu, à peu près comme 'merde' mais encore plus courant et un peu moins tabou. Ça passe entre amis ; à éviter avec des clients, des chefs que vous ne connaissez pas ou en contexte formel.",
  "Ladder level 4, STRONG — for genuine anger or shock. Friends only; heads will turn if you shout it in public.": "Niveau 4 de l'échelle, FORT — pour une colère ou un choc réels. Entre amis seulement ; crié en public, les têtes se tournent.",
  "Ladder level 5, STRONG insult — a real attack, never banter-safe with strangers. LEGAL WARNING: calling a stranger 'Arschloch' in public is Beleidigung, a criminal offence in Germany, and courts have fined it at over 1,000 euros.": "Niveau 5 de l'échelle, insulte FORTE — une vraie agression, jamais utilisable en plaisanterie avec des inconnus. AVERTISSEMENT JURIDIQUE : traiter un inconnu d'Arschloch en public est une Beleidigung, un délit pénal en Allemagne, et les tribunaux l'ont sanctionné de plus de 1 000 euros.",
  "Ladder level 6, VERY STRONG — fighting words that can start a physical fight and a criminal complaint. Never safe, not even as banter with most friends. Learn to recognise it, don't use it.": "Niveau 6 de l'échelle, TRÈS FORT — des mots de combat qui peuvent déclencher une bagarre et une plainte pénale. Jamais sans risque, pas même en plaisantant avec la plupart des amis. Apprenez à le reconnaître, ne l'employez pas.",
  "lassen + infinitive: you let the hair do the growing. Also the polite warning that you want almost nothing cut.": "lassen + infinitif : on laisse les cheveux pousser. C'est aussi l'avertissement poli qu'on ne veut presque rien couper.",
  "Leaving": "Partir",
  "Level 2, medium-mild — like English 'damn'; fine among adults, avoid formal settings": "Niveau 2, moyen-doux — comme le 'damn' anglais ; ça passe entre adultes, à éviter dans un cadre formel",
  "Literally 'he doesn't have all his cups in the cupboard'. Teasing between friends, harsh about strangers — dose carefully.": "Littéralement 'il n'a pas toutes ses tasses dans le placard'. Taquin entre amis, dur à propos d'inconnus — à doser avec soin.",
  "Literally 'it is not good eating cherries with him' — a warning about someone's temper. Old, odd grammar, still completely current.": "Littéralement 'avec lui il ne fait pas bon manger des cerises' — un avertissement sur le caractère de quelqu'un. Grammaire ancienne et bizarre, toujours parfaitement actuelle.",
  "Literally 'luck game' — the umbrella and legal term for gambling. Glücksspiel kann süchtig machen is the mandatory warning on every ad.": "Littéralement 'jeu de chance' — le terme générique et juridique pour les jeux d'argent. Glücksspiel kann süchtig machen est l'avertissement obligatoire sur chaque publicité.",
  "Literally 'you can remove that make-up' — a plan dismissed as never going to happen. Blunt but not rude between friends.": "Littéralement 'tu peux te démaquiller de ça' — un projet balayé comme irréalisable. Franc mais pas impoli entre amis.",
  "Loadout": "Équipement",
  "Logisch! is also a casual \"obviously\"": "Logisch! est aussi un 'évidemment' décontracté",
  "Making a move": "Faire le premier pas",
  "Making plans": "Faire des projets",
  "medium insult — banter-safe among close friends with the right tone": "insulte moyenne — passe en plaisanterie entre amis proches, avec le bon ton",
  "MEDIUM insult — with a grin and the right tone it's banter-safe among close friends; shouted at a stranger (e.g. in traffic) it's an insult that can be reported to the police.": "Insulte MOYENNE — avec un sourire et le bon ton, elle passe en plaisanterie entre amis proches ; criée à un inconnu (dans la circulation par exemple), c'est une insulte que l'on peut signaler à la police.",
  "medium-strong — banter only with thick-skinned close friends": "assez fort — à réserver aux plaisanteries entre amis proches qui ont le cuir épais",
  "MEDIUM-STRONG — literally 'full fencepost'. Popular in traffic rants and among friends with thick skin; genuinely insulting to anyone else.": "MOYEN-FORT — littéralement 'piquet de clôture entier'. Populaire dans les coups de gueule au volant et entre amis au cuir épais ; réellement insultant pour tous les autres.",
  "MEDIUM-STRONG — softer than 'Arschloch' but still a real accusation of being a bad person. Between friends it can signal genuine hurt, not banter.": "MOYEN-FORT — plus doux que 'Arschloch' mais toujours une vraie accusation d'être quelqu'un de mauvais. Entre amis, cela peut signaler une blessure réelle, pas une vanne.",
  "Medium, extremely common — genuine outrage or playful disbelief depending on tone. Fine among friends and family.": "Moyen, extrêmement courant — indignation sincère ou incrédulité joueuse selon le ton. Ça passe entre amis et en famille.",
  "Messaging — informal (du); in formal calls: Ich schreibe Ihnen eine Nachricht": "Écrire des messages — informel (du) ; en contexte formel : Ich schreibe Ihnen eine Nachricht",
  "Meta": "Méta",
  "MILD-MEDIUM — dismissive ('you're not right in the head') rather than aggressive. Banter-safe among friends.": "DOUX À MOYEN — dédaigneux ('tu n'as pas toute ta tête') plutôt qu'agressif. Passe en plaisanterie entre amis.",
  "MILD-MEDIUM — often affectionate among friends and family ('you silly thing'). Still rude to strangers.": "DOUX À MOYEN — souvent affectueux entre amis et en famille ('espèce de nigaud'). Reste impoli envers des inconnus.",
  "mild-medium — often affectionate banter among friends": "doux à moyen — souvent une taquinerie affectueuse entre amis",
  "MILD-MEDIUM, very common in Bavaria and Austria — between friends it's usually affectionate teasing. Banter-safe with friends; rude to strangers.": "DOUX À MOYEN, très courant en Bavière et en Autriche — entre amis, c'est généralement une taquinerie affectueuse. Passe en plaisanterie entre amis ; impoli envers des inconnus.",
  "mithelfen — pitching in. The morning-after miracle that separates friends from guests.": "mithelfen — donner un coup de main. Le miracle du lendemain matin qui sépare les amis des invités.",
  "MOCK OUTRAGE after a spoiler — hand on forehead, theatrical. 'versauen' = to ruin/mess up, casual and a shade crude but totally normal. Genuine anger uses the exact same words, so the grin does the sorting.": "INDIGNATION FEINTE après un spoiler — main sur le front, théâtral. 'versauen' = gâcher, décontracté et un brin cru, mais tout à fait normal. La vraie colère emploie exactement les mêmes mots ; c'est donc le sourire qui fait le tri.",
  "mocking the classic 'Spiegel-Poser', a fixture of every gym; casual, said behind their back": "moqueur envers le classique 'Spiegel-Poser', présent dans toute salle de sport ; décontracté, dit dans son dos",
  "mocking, informal; the Aluhut is THE German ridicule image for conspiracists": "moqueur, informel ; l'Aluhut est LE symbole allemand de la moquerie envers les complotistes",
  "mögen + person = plain liking, zero romance implied — safe about colleagues, friends, your partner's brother. Speech usually adds 'gern' ('Ich mag ihn echt gern'), which textbooks call redundant and natives say anyway. Careful: 'Ich mag dich' said TO a date is a soft confession, one rung below 'Ich hab dich lieb'.": "mögen + personne = affection simple, aucune romance impliquée — sans risque à propos de collègues, d'amis, du frère de votre partenaire. À l'oral on ajoute d'ordinaire 'gern' ('Ich mag ihn echt gern'), que les manuels jugent redondant et que les natifs disent quand même. Attention : 'Ich mag dich' adressé À un rendez-vous galant est un aveu léger, un cran en dessous de 'Ich hab dich lieb'.",
  "nachfragen — following up. The sentence that saves the friendship.": "nachfragen — relancer. La phrase qui sauve l'amitié.",
  "neu laden = to reload — neu as an adverb before the verb; einfach shrugs it casual.": "neu laden = recharger — neu en adverbe devant le verbe ; einfach donne le ton décontracté.",
  "Neutral opener that signals something is on your mind; works with friends and family.": "Entrée en matière neutre qui signale qu'on a quelque chose sur le cœur ; convient aux amis et à la famille.",
  "neutral small talk; works with anyone — casually dropped article is typical": "small talk neutre ; convient à tout le monde — l'article qu'on laisse tomber est typique",
  "neutral word; among friends it's almost always 'die Kippe'": "mot neutre ; entre amis, c'est presque toujours 'die Kippe'",
  "Neutral-casual; 'Abi' is what everyone says — the full 'Abitur' sounds formal.": "Neutre-décontracté ; tout le monde dit 'Abi' — le complet 'Abitur' fait formel.",
  "Neutral-casual; 'kriegen' is the spoken form of 'bekommen'.": "Neutre-décontracté ; 'kriegen' est la forme orale de 'bekommen'.",
  "Neutral-colloquial; 'zuschlagen' = to throw a punch, to strike.": "Neutre-familier ; 'zuschlagen' = donner un coup, frapper.",
  "NEUTRAL-FORMAL, the first thing you say when someone returns your call — at work it's practically obligatory. 'der Rückruf' is the noun hiding inside 'zurückrufen'; with friends you'd just say 'Danke, dass du zurückrufst.'": "NEUTRE-FORMEL, la première chose que l'on dit quand quelqu'un vous rappelle — au travail, c'est pratiquement obligatoire. 'der Rückruf' est le nom caché dans 'zurückrufen' ; entre amis, on dirait simplement 'Danke, dass du zurückrufst.'",
  "Neutral, casual — a no-fuss way to not drink without explaining yourself. No justification expected.": "Neutre, décontracté — une façon sans histoires de ne pas boire sans se justifier. Aucune explication n'est attendue.",
  "Neutral, casual 'hab'. The standard sequel to Verspätung — deliver it with weary resignation, not anger.": "Neutre, 'hab' décontracté. La suite standard de Verspätung — à dire avec une résignation lasse, pas avec colère.",
  "Neutral, common — disbelief that hovers between amused and appalled. Safe with anyone informal.": "Neutre, courant — une incrédulité entre amusement et effroi. Sans risque avec n'importe qui, en registre informel.",
  "Neutral, friendly — the standard joke opener among friends, family and colleagues. 'den' refers to der Witz.": "Neutre, amical — l'ouverture standard d'une blague entre amis, famille et collègues. 'den' renvoie à der Witz.",
  "Neutral, respectful — THE standard phrase for someone in recovery from alcoholism. Not slang, not a euphemism; it conveys respect for the achievement.": "Neutre, respectueux — LA formule standard pour quelqu'un en rémission d'un alcoolisme. Ni argot ni euphémisme ; elle rend hommage à l'exploit.",
  "Neutral, to friends/family/partner. THE suggestion — a leisurely loop, especially Sunday afternoon.": "Neutre, à des amis, la famille ou son partenaire. LA suggestion — une boucle tranquille, surtout le dimanche après-midi.",
  "Neutral, to whoever planned the route. 'Die Tour' is the casual word for a planned hike.": "Neutre, à celui qui a préparé l'itinéraire. 'Die Tour' est le mot décontracté pour une randonnée planifiée.",
  "News German: eine Bombe wurde gefunden und entschärft. The colloquial praise needs the definite article — das ist die Bombe = that's brilliant; with eine it is taken literally.": "Allemand des informations : eine Bombe wurde gefunden und entschärft. L'éloge familier exige l'article défini — das ist die Bombe = c'est génial ; avec eine, on le comprend au sens propre.",
  "noch kein(e) softens the negation to 'not yet / not by itself' — the standard phrasing of this warning in German academic prose.": "noch kein(e) adoucit la négation en 'pas encore / pas à soi seul' — la formulation standard de cet avertissement dans la prose académique allemande.",
  "Not just 'differently' but inverted — you think the cause and the effect have been swapped. 'andersrum' is the spoken form of 'andersherum', and 'seh's' is 'sehe es'. Direct but not rude among friends and colleagues.": "Pas seulement 'autrement' mais à l'envers — vous pensez que la cause et l'effet ont été intervertis. 'andersrum' est la forme orale de 'andersherum', et 'seh's' vaut 'sehe es'. Direct mais pas impoli entre amis et collègues.",
  "Note the preposition: 'auf den Weihnachtsmarkt' (auf + Akkusativ), not zu or in. From late November this is THE default suggestion for dates, friends and colleagues alike — nobody ever needs a reason.": "Attention à la préposition : 'auf den Weihnachtsmarkt' (auf + accusatif), pas zu ni in. À partir de fin novembre, c'est LA proposition par défaut pour un rendez-vous, des amis comme des collègues — personne n'a jamais besoin d'une raison.",
  "Noun phrase + und + consequence — a conditional without wenn; landen in = to end up in, informal and vivid.": "Groupe nominal + und + conséquence — une conditionnelle sans wenn ; landen in = finir dans, informel et imagé.",
  "oder so = or something / or whatever (casual suggestions)": "oder so = ou un truc comme ça (suggestions décontractées)",
  "Officially the elektronische Gesundheitskarte (eGK); colloquially Versichertenkarte or Krankenkassenkarte. You usually have a few weeks to present it retroactively": "Officiellement la elektronische Gesundheitskarte (eGK) ; familièrement Versichertenkarte ou Krankenkassenkarte. On a généralement quelques semaines pour la présenter après coup",
  "On Discord, 'der Server' means the community space — the same word as a game server; context decides which. Casual invitation.": "Sur Discord, 'der Server' désigne l'espace communautaire — le même mot que pour un serveur de jeu ; le contexte tranche. Invitation décontractée.",
  "One of the most-used verbs in spoken German. 'Mich nervt an ihm, dass ...' = what annoys me about him is that ... Bare version between friends: 'Du nervst!' = you're being annoying.": "L'un des verbes les plus employés à l'oral allemand. 'Mich nervt an ihm, dass ...' = ce qui m'agace chez lui, c'est que ... Version nue entre amis : 'Du nervst!' = tu es pénible.",
  "One word does what English needs five for — no body part needed, everyone knows it's the ankle. Keep this for friends; at the doctor's you'd say 'Ich habe mir den Knöchel verstaucht.'": "Un seul mot fait ce que l'anglais fait en cinq — aucune partie du corps nécessaire, tout le monde sait qu'il s'agit de la cheville. Gardez cela pour les amis ; chez le médecin, vous diriez 'Ich habe mir den Knöchel verstaucht.'",
  "Only with close friends or your partner — for many Germans, vote choice is genuinely private (Wahlgeheimnis culture). Asking a colleague or acquaintance can land as intrusive.": "Seulement avec des amis proches ou son partenaire — pour beaucoup d'Allemands, le choix électoral est réellement privé (culture du Wahlgeheimnis). Le demander à un collègue ou à une connaissance peut sembler intrusif.",
  "Opinion": "Opinion",
  "Ordering food": "Commander à manger",
  "Peak German summer household knowledge: you close the Rollladen in the morning and keep the heat out all day. 'die Bude' = the place/gaff — casual and affectionate about your own flat, mildly rude about someone else's.": "Le savoir domestique estival allemand par excellence : on ferme les Rollladen le matin et on garde la chaleur dehors toute la journée. 'die Bude' = le logement — décontracté et affectueux pour le sien, un peu impoli pour celui d'un autre.",
  "personal question — fine among friends or partners, odd with strangers or colleagues; note glauben an + accusative": "question personnelle — ça passe entre amis ou en couple, bizarre avec des inconnus ou des collègues ; notez glauben an + accusatif",
  "Plans": "Projets",
  "Platform warning before train doors close": "Avertissement sur le quai avant la fermeture des portes du train",
  "Players say Wishlist even though Steam's German UI says Wunschliste; 'schon ewig' = for ages. Neutral-casual.": "Les joueurs disent Wishlist même si l'interface allemande de Steam affiche Wunschliste ; 'schon ewig' = depuis une éternité. Neutre-décontracté.",
  "Playful defensiveness, mild — said with mock indignation when friends laugh at your mishap. Casual settings.": "Défense joueuse, douce — dit avec une indignation feinte quand les amis rient de votre mésaventure. Contextes décontractés.",
  "pleite — from bankruptcy, used casually. 'gerade' makes it temporary.": "pleite — venu de la faillite, employé familièrement. 'gerade' le rend temporaire.",
  "plural 'Jungs' = guys, lads (colloquial)": "pluriel 'Jungs' = les gars, les mecs (familier)",
  "polite check with friends before lighting up; expected around non-smokers": "petite vérification polie auprès des amis avant d'allumer une cigarette ; attendue en présence de non-fumeurs",
  "polite warning shot before or instead of details; 'heikel' = delicate/tricky": "coup de semonce poli avant ou à la place des détails ; 'heikel' = délicat, épineux",
  "polite-casual at the salon; was = etwas in spoken German": "poli et décontracté au salon ; was = etwas à l'oral en allemand",
  "Position callout": "Annonce de position",
  "Post-betrayal confession to close friends or a therapist. Raw and serious — the 'einfach' carries the helplessness. Vertrauen wants a dative object here: niemandem.": "Confidence après une trahison, à des amis proches ou à un thérapeute. Brute et sérieuse — le 'einfach' porte l'impuissance. Vertrauen exige ici un objet au datif : niemandem.",
  "Post-breakup confession to close friends; serious and vulnerable, no banter register.": "Confidence après une rupture, à des amis proches ; sérieuse et vulnérable, pas de registre badin.",
  "Pronounced letter by letter, pe-em-ess, and said openly to partners and close friends. The pre-emptive 'nimm's nicht persönlich' is what turns it into a heads-up rather than a complaint.": "Prononcé lettre par lettre, pé-em-esse, et dit ouvertement aux partenaires et aux amis proches. Le 'nimm's nicht persönlich' anticipé transforme la chose en avertissement plutôt qu'en plainte.",
  "Reacting": "Réagir",
  "Reassuring": "Rassurer",
  "Relationship status": "Statut relationnel",
  "Reporting a problem": "Signaler un problème",
  "Request": "Demande",
  "resigned, informal; standard line among worried friends of a Schwurbler": "résigné, informel ; la réplique standard entre amis inquiets d'un Schwurbler",
  "resigned; extremely common among friends and family of someone who's gone down the hole": "résigné ; extrêmement courant chez les amis et la famille de quelqu'un qui a plongé",
  "Retail-investor bravado among friends; 'nachkaufen' = to buy more of what you already hold": "bravade de petit porteur entre amis ; 'nachkaufen' = racheter davantage de ce qu'on détient déjà",
  "Rhetorical exasperation about media/politics. Bonding move among friends; the 'mal ehrlich' invites shared sighing.": "Exaspération rhétorique au sujet des médias ou de la politique. Un geste de connivence entre amis ; le 'mal ehrlich' invite au soupir partagé.",
  "Routine": "Routine",
  "Said to friends — who will name it instantly: that's a red flag ('eine Red Flag' — the English term is standard German dating slang now). Controlling behaviour, not love.": "Dit à des amis — qui le nommeront immédiatement : c'est un red flag ('eine Red Flag' — le terme anglais est désormais l'argot de rencontres standard en allemand). Un comportement de contrôle, pas de l'amour.",
  "Said while handing over the Mitbringsel at the door, informal.": "Dit en tendant le Mitbringsel sur le pas de la porte, informel.",
  "SARCASM — 'danke auch' is never sincere; it's the flat, annoyed 'thanks a bunch'. Jokey between friends, but the irritation underneath is real.": "SARCASME — 'danke auch' n'est jamais sincère ; c'est le 'merci bien' plat et agacé. Blagueur entre amis, mais l'irritation dessous est réelle.",
  "Sarcastic, mild — slightly more pointed than 'Sehr witzig.' Friends and family; signals the joke was at your expense.": "Sarcastique, doux — un peu plus pointu que 'Sehr witzig.' Amis et famille ; signale que la blague était à vos dépens.",
  "Say this when someone is about to see mutual friends or family. To several listeners, use 'Grüßt'.": "À dire quand quelqu'un s'apprête à voir des amis communs ou de la famille. À plusieurs interlocuteurs, employez 'Grüßt'.",
  "Scheduling": "Planification",
  "schlauchen — sapping your energy like a hose. Colloquial and exactly right.": "schlauchen — pomper l'énergie comme un tuyau. Familier et parfaitement juste.",
  "schreiben = to write / spell (informal)": "schreiben = écrire / orthographier (informel)",
  "Seasons": "Saisons",
  "self-deprecating joke; 'ich schwör' is casual spoken German": "blague d'autodérision ; 'ich schwör' est de l'allemand parlé décontracté",
  "separable: 'Ich probier mal was aus.' Casual speech clips it to 'probieren': 'Ich probier mal ne andere Waffe'": "à particule séparable : 'Ich probier mal was aus.' À l'oral décontracté, on l'abrège en 'probieren' : 'Ich probier mal ne andere Waffe'",
  "sich befassen mit = to engage with; the je/desto frame around a negation — avoidance measured in growth.": "sich befassen mit = se pencher sur ; la structure je/desto autour d'une négation — l'évitement mesuré en croissance.",
  "sich etwas freihalten — keeping a day open. The advance reservation of friendship.": "sich etwas freihalten — se garder une journée libre. La réservation anticipée de l'amitié.",
  "sich hinlegen — putting yourself down. 'mal' makes it casual, not dramatic.": "sich hinlegen — s'allonger. 'mal' rend la chose décontractée, pas dramatique.",
  "sich kurzschließen = to quickly sync (colloquial workplace); aneinander vorbeiarbeiten is a set idiom.": "sich kurzschließen = se concerter rapidement (familier, au travail) ; aneinander vorbeiarbeiten est une expression figée.",
  "Slang": "Argot",
  "Slang — the English loan stays English; ein deutsches Bad is a bathroom": "Argot — l'emprunt anglais reste anglais ; ein deutsches Bad est une salle de bains",
  "Slang (voll = really/very)": "Argot (voll = vraiment, très)",
  "Slang expression of enthusiasm": "Expression d'enthousiasme en argot",
  "Slightly fuller version of the same question. Both are informal; with Sie: 'Was für Musik hören Sie?' — rare, music talk is almost always du-territory.": "Version un peu plus complète de la même question. Les deux sont informelles ; avec Sie : 'Was für Musik hören Sie?' — rare, car parler musique relève presque toujours du tutoiement.",
  "Small-talk staple with international friends and colleagues; expect Germans to argue about their own answer.": "Un classique du small talk avec des amis et collègues internationaux ; attendez-vous à voir les Allemands débattre de leur propre réponse.",
  "Some platforms add friends through masculine 'der Freundescode'; accusative is 'deinen Freundescode'.": "Certaines plateformes ajoutent des amis via le masculin 'der Freundescode' ; à l'accusatif : 'deinen Freundescode'.",
  "spiegelglatt — mirror-smooth. The radio traffic warning word.": "spiegelglatt — lisse comme un miroir. Le mot d'avertissement de l'info-trafic à la radio.",
  "Spoken as a warning: unfinished, buggy, roadmap promises. Used unmodified as an English noun (der Early Access).": "Dit comme un avertissement : inachevé, bugué, promesses de feuille de route. Employé tel quel comme nom anglais (der Early Access).",
  "spoken clip of 'Dispositionskredit'; 'im Dispo sein' = to be overdrawn — casual, everyone says it": "abrégé oral de 'Dispositionskredit' ; 'im Dispo sein' = être à découvert — décontracté, tout le monde le dit",
  "Spoken word order: the demonstrative 'den/der' instead of 'ihn/er' is completely normal about people in casual speech — familiar, not rude. 'in Ordnung sein' = to be a decent sort.": "Ordre des mots de l'oral : le démonstratif 'den/der' au lieu de 'ihn/er' est tout à fait normal à propos des gens en registre décontracté — familier, pas impoli. 'in Ordnung sein' = être quelqu'un de bien.",
  "standard match-day question among friends, colleagues, in the Kneipe": "la question standard les jours de match, entre amis, collègues, au Kneipe",
  "Standard term in news and casual talk alike; can get heated between generations.": "Terme standard aussi bien dans l'info que dans la conversation décontractée ; peut s'échauffer entre générations.",
  "Standard third-person relationship analysis among friends; casual armchair-psychology weight.": "L'analyse de couple à la troisième personne entre amis ; psychologie de comptoir, ton décontracté.",
  "Statistically the most likely reply you'll get in any German city. 'selber' is the colloquial form of 'selbst' and it's what you'll actually hear. Handy in reverse too, when someone asks you.": "Statistiquement la réponse la plus probable dans n'importe quelle ville allemande. 'selber' est la forme familière de 'selbst' et c'est ce que vous entendrez réellement. Pratique aussi dans l'autre sens, quand on vous le demande.",
  "Status callout": "Annonce d'état",
  "Straight from the Kiyosaki playbook; drop it in money talks with friends — some will nod, some will roll their eyes": "Tout droit sorti du répertoire de Kiyosaki ; glissez-le dans les discussions d'argent entre amis — certains hocheront la tête, d'autres lèveront les yeux au ciel",
  "Strong accusation — normal among friends, conversation-ending in a debate; die Desinformation is the more clinical term": "Accusation grave — normale entre amis, elle met fin à la conversation dans un débat ; die Desinformation est le terme plus clinique",
  "Strong agreement": "Accord appuyé",
  "Strong verb with a vowel change: ich stehle, du stiehlst, er stiehlt, gestohlen. The casual everyday word is klauen.": "Verbe fort avec alternance vocalique : ich stehle, du stiehlst, er stiehlt, gestohlen. Le mot décontracté du quotidien est klauen.",
  "Strong, final dislike — you've given up on this person. Friends-only register: saying it about a colleague inside the office is a political act. Remember: ausstehen has no positive form.": "Aversion forte et définitive — vous avez renoncé à cette personne. Registre réservé aux amis : le dire d'un collègue au bureau est un acte politique. À retenir : ausstehen n'a pas de forme positive.",
  "Strong, vulgar — aimed at a person it's aggressive; blurted at bad news it means 'you have got to be kidding'. Among close friends it can be half-joking; never at strangers or at work.": "Fort, vulgaire — visant une personne, c'est agressif ; lâché face à une mauvaise nouvelle, cela veut dire 'c'est une blague ou quoi'. Entre amis proches, cela peut être à moitié pour rire ; jamais envers des inconnus ni au travail.",
  "Strong, vulgar — an aggressive order to leave. Sometimes rough banter among very close friends, but hostile to anyone else.": "Fort, vulgaire — un ordre agressif de partir. Parfois une vanne rugueuse entre amis très proches, mais hostile pour tous les autres.",
  "stronger and less casual than widerlich finden": "plus fort et moins décontracté que widerlich finden",
  "Sunday is legally protected quiet time: no drill, no lawnmower, and in strict houses no washing machine either. 'Das gibt Ärger' = that'll cause trouble — the standard warning formula.": "Le dimanche est un temps de repos protégé par la loi : pas de perceuse, pas de tondeuse, et dans les immeubles stricts pas de machine à laver non plus. 'Das gibt Ärger' = ça va faire des histoires — la formule d'avertissement standard.",
  "Surprise": "Surprise",
  "Sweet, slightly childlike peace offer — usually said with an outstretched hand or open arms. The kindergarten echo ('Vertragt euch!') is exactly what makes it disarming between adults. Partner, family, close friends.": "Offre de paix douce, un peu enfantine — dite d'ordinaire main tendue ou bras ouverts. L'écho de la maternelle ('Vertragt euch!') est précisément ce qui la rend désarmante entre adultes. Partenaire, famille, amis proches.",
  "Symptom": "Symptôme",
  "talking about quitting with friends or partner": "parler d'arrêter, avec des amis ou son partenaire",
  "tanken — refuelling. Driving on the warning light is called auf Reserve fahren.": "tanken — faire le plein. Rouler avec le voyant allumé s'appelle auf Reserve fahren.",
  "Team play": "Jeu d'équipe",
  "Teasing between partners or friends; 'etwa' adds the playful gotcha tone.": "Taquinerie entre partenaires ou amis ; 'etwa' apporte le ton badin du je-t'y-prends.",
  "Telling time": "Dire l'heure",
  "Texting": "Textos",
  "That little 'mal' turns the question into a casual favour. Without it the sentence is still correct, just blunter.": "Ce petit 'mal' transforme la question en un service décontracté. Sans lui, la phrase reste correcte, simplement plus abrupte.",
  "The -chen ending makes it small and playful. Warm among friends and with children; it would sound odd in an office.": "La terminaison -chen le rend petit et joueur. Chaleureux entre amis et avec des enfants ; au bureau, cela sonnerait bizarre.",
  "The 'doch' does the work: it concedes that things went your way and not mine. Spelling: 'recht haben' lowercase is the usual form today — the 1996 reform pushed 'Recht haben', but the 2006 revision allowed both again. Warm between friends — or, with the right sigh, thoroughly grudging.": "C'est le 'doch' qui fait le travail : il concède que les choses ont tourné à ton avantage et non au mien. Orthographe : 'recht haben' en minuscule est la forme habituelle aujourd'hui — la réforme de 1996 imposait 'Recht haben', la révision de 2006 a de nouveau autorisé les deux. Chaleureux entre amis — ou, avec le bon soupir, parfaitement à contrecœur.",
  "The 'gerade' matters — asking about the current obsession, not the all-time answer. Casual, du-form.": "Le 'gerade' compte — on demande l'obsession du moment, pas la réponse de toujours. Décontracté, forme en du.",
  "The 'so meine' is the whole trick: it turns specific doubts into a mild, almost casual reservation, which is far more damaging in German conversation than a direct objection.": "Le 'so meine' est toute l'astuce : il transforme des doutes précis en une réserve douce, presque anodine, ce qui est bien plus dévastateur dans une conversation allemande qu'une objection directe.",
  "The 2026 reflex, said the way 'google it' was said in 2010 — casual, to anyone; note DIE KI (künstliche Intelligenz is feminine).": "Le réflexe de 2026, dit comme on disait 'google-le' en 2010 — décontracté, à n'importe qui ; notez DIE KI (künstliche Intelligenz est féminin).",
  "The Angst compounds take no article: Höhenangst, Flugangst, Prüfungsangst (exam nerves). 'total' is the casual spoken intensifier. Said on ladders, bridges and viewing platforms nationwide.": "Les composés en Angst se passent d'article : Höhenangst, Flugangst, Prüfungsangst (le trac d'examen). 'total' est l'intensificateur décontracté à l'oral. Dit sur les échelles, les ponts et les plateformes panoramiques du pays entier.",
  "The Anprobe-zu-Hause strategy: order both, keep one, return the other; casual du-register": "La stratégie Anprobe-zu-Hause : commander les deux, en garder un, renvoyer l'autre ; registre du, décontracté",
  "The apology that reopens a friendship. 'sich melden' = to get in touch; German expects a reason to follow, but the honest 'Ich hab's einfach nicht geschafft' counts as one.": "L'excuse qui rouvre une amitié. 'sich melden' = donner de ses nouvelles ; l'allemand attend qu'une raison suive, mais l'honnête 'Ich hab's einfach nicht geschafft' en tient lieu.",
  "The apology-shaped chase between colleagues on the same level: admitting you're being annoying is exactly what makes it acceptable. 'nerven' = to be annoying. Too casual for your boss — there you'd write 'Ich wollte nochmal daran erinnern.'": "La relance déguisée en excuse entre collègues de même niveau : admettre qu'on est pénible est précisément ce qui la rend acceptable. 'nerven' = agacer. Trop décontracté pour votre chef — là, vous écririez 'Ich wollte nochmal daran erinnern.'",
  "The barber will ask you this; colloquially you'll also hear 'Wie viel Millimeter an den Seiten?'": "Le coiffeur vous posera cette question ; en registre familier, vous entendrez aussi 'Wie viel Millimeter an den Seiten?'",
  "The belated introduction after two years of nodding in the stairwell. Germans put 'der/die' in front of their own first name in casual speech — 'Ich bin der Tim', 'Ich bin die Sarah' — friendly and very spoken. The 'übrigens' makes it sound spontaneous rather than overdue.": "La présentation tardive après deux ans de hochements de tête dans la cage d'escalier. À l'oral décontracté, les Allemands placent 'der/die' devant leur propre prénom — 'Ich bin der Tim', 'Ich bin die Sarah' — amical et très parlé. Le 'übrigens' donne un air spontané plutôt que tardif.",
  "The bots are used like first names, no article: Ich hab Claude/ChatGPT gefragt — exactly how you'd report asking a friend; completely normal in casual speech.": "Les bots s'emploient comme des prénoms, sans article : Ich hab Claude/ChatGPT gefragt — exactement comme on raconterait avoir demandé à un ami ; tout à fait normal à l'oral décontracté.",
  "The casual imperative is 'Misch'; 'die Karten mischen' is the normal phrase for shuffling.": "L'impératif décontracté est 'Misch' ; 'die Karten mischen' est la tournure normale pour battre les cartes.",
  "The casual tier. Beste Grüße, Viele Grüße, VG: the ladder descends with familiarity.": "Le cran décontracté. Beste Grüße, Viele Grüße, VG : l'échelle descend à mesure qu'on se connaît.",
  "the casual word for Rad fahren": "le mot décontracté pour Rad fahren",
  "The classic couple question. 'Sich (Dativ) etwas holen' is the casual verb for getting a pet.": "La question classique du couple. 'Sich (Dativ) etwas holen' est le verbe décontracté pour prendre un animal.",
  "The classic hypocrite's hedge — announcing that you won't lästern IS the start of lästern, and everyone knows it. Delivered with a grin among friends; the particle 'ja' makes it wink.": "La précaution hypocrite classique — annoncer qu'on ne va pas lästern EST le début du lästern, et tout le monde le sait. Dit avec un sourire entre amis ; la particule 'ja' fait le clin d'œil.",
  "The classic no-fault breakup explanation — sad but blame-free. What people tell friends afterwards.": "L'explication de rupture classique sans coupable — triste mais sans reproche. Ce qu'on raconte ensuite à ses amis.",
  "The clean no. Making it a blanket rule ('grundsätzlich') instead of a judgement about this person is what saves the friendship — a stated principle is something Germans will accept almost without argument.": "Le non net. En faire une règle générale ('grundsätzlich') plutôt qu'un jugement sur cette personne, c'est ce qui sauve l'amitié — un principe énoncé, les Allemands l'acceptent presque sans discuter.",
  "The clean, non-rude disagreement — 'widersprechen' takes the dative (dir, Ihnen). Fine at work and with friends; slipping in 'jetzt mal' makes it friendlier still.": "Le désaccord net et non impoli — 'widersprechen' se construit avec le datif (dir, Ihnen). Ça passe au travail et entre amis ; glisser 'jetzt mal' le rend encore plus amical.",
  "The colloquial breakup phrase: mit jemandem Schluss machen. What people actually say about boyfriends and girlfriends; 'sich trennen' is the more neutral word, standard for long-term or married couples.": "L'expression familière de la rupture : mit jemandem Schluss machen. C'est ce que les gens disent vraiment à propos d'un copain ou d'une copine ; 'sich trennen' est le mot plus neutre, standard pour les couples de longue date ou mariés.",
  "The complete form is useful in writing and careful speech. With friends, 'Versteh ich, aber ...' is the usual quick softener before disagreeing.": "La forme complète est utile à l'écrit et dans un discours soigné. Entre amis, 'Versteh ich, aber ...' est l'adoucisseur rapide habituel avant de contredire.",
  "THE confidentiality contract of German friendship — said BEFORE the secret, answered with 'Klar!'. 'unter uns' = between us. Breaking it is a real offence.": "LE contrat de confidentialité de l'amitié allemande — dit AVANT le secret, auquel on répond 'Klar!'. 'unter uns' = entre nous. Le rompre est une vraie faute.",
  "The daily 6 p.m. question. 'heute Abend' does the work of 'for dinner' — spoken German needs no meal word. Warning: answering 'Mir egal' starts a longer discussion than any menu.": "La question quotidienne de 18 heures. 'heute Abend' fait le travail de 'pour le dîner' — l'allemand parlé n'a pas besoin du nom du repas. Attention : répondre 'Mir egal' déclenche une discussion plus longue que n'importe quel menu.",
  "THE dating-scene diagnosis of the decade; said casually but half-seriously about anyone who won't commit.": "LE diagnostic de la décennie côté rencontres ; dit avec décontraction mais à moitié sérieusement de quiconque refuse de s'engager.",
  "The default armchair diagnosis for a bad ex — everyday venting between friends. Casual there, but a genuine insult said to someone's face.": "Le diagnostic de comptoir par défaut pour un mauvais ex — décharge quotidienne entre amis. Décontracté là, mais une vraie insulte dit en face.",
  "The default Grußformel — never wrong, never exciting. MfG in casual shorthand.": "La Grußformel par défaut — jamais fausse, jamais palpitante. En abrégé décontracté : MfG.",
  "The diplomatic way to raise noise: blame the building, not the neighbour. Half warning ('so watch out'), half apology ('so sorry about us') — the listener decides which.": "La manière diplomate d'aborder le bruit : blâmer l'immeuble, pas le voisin. Mi-avertissement ('donc fais attention'), mi-excuse ('désolé pour nous') — c'est l'auditeur qui tranche.",
  "The dramatic version for partners and close friends — du-form territory, carries real weight": "La version dramatique pour les partenaires et les amis proches — territoire du du, avec un vrai poids",
  "The embarrassment-avoidance rule. Half of all lost keys are in the other jacket.": "La règle anti-embarras. La moitié des clés perdues sont dans l'autre veste.",
  "The everyday refusal — 'Lust haben' = to feel like doing something, with no matching English verb. With an object it takes auf + Akkusativ: 'keine Lust auf Kino'. Among friends this counts as a complete reason.": "Le refus de tous les jours — 'Lust haben' = avoir envie de faire quelque chose, sans verbe anglais équivalent. Avec un objet, il se construit avec auf + accusatif : 'keine Lust auf Kino'. Entre amis, cela compte comme une raison complète.",
  "THE everyday spoken word for angry — more common in real life than 'wütend'. 'sauer auf + Akkusativ': 'Ich bin sauer auf dich' = I'm mad at you. Informal but not rude.": "LE mot du quotidien à l'oral pour en colère — plus courant dans la vraie vie que 'wütend'. 'sauer auf + accusatif' : 'Ich bin sauer auf dich' = je t'en veux. Informel mais pas impoli.",
  "THE everyday way to say it. 'aufs Klo' is casual and completely normal with family, a partner or friends — 'auf die Toilette' is the neutral version for anywhere else. The 'mal' softens it into a passing remark rather than an announcement.": "LA façon quotidienne de le dire. 'aufs Klo' est décontracté et parfaitement normal en famille, en couple ou entre amis — 'auf die Toilette' est la version neutre pour tout le reste. Le 'mal' en fait une remarque en passant plutôt qu'une annonce.",
  "The excited announcement to friends and family. 'Einen Antrag machen' is the standard idiom for proposing.": "L'annonce enthousiaste aux amis et à la famille. 'Einen Antrag machen' est l'expression standard pour faire sa demande.",
  "The eye-roll cliché — every interviewer has heard it a thousand times. Learn it so you can avoid it; among friends it's only said ironically.": "Le cliché qui fait lever les yeux au ciel — tout recruteur l'a entendu mille fois. Apprenez-le pour l'éviter ; entre amis, on ne le dit qu'ironiquement.",
  "The feud-avoidance move in a shared laundry room: you ask even though you both know the answer, and even though they aren't standing there. Asking first is the entire trick.": "Le geste anti-querelle dans une buanderie commune : on demande alors que tous deux connaissent la réponse, et alors même que l'autre n'est pas là. Demander d'abord, c'est toute l'astuce.",
  "The first question every friend asks. Casual, expected, and everyone wants the full story.": "La première question que pose chaque ami. Décontractée, attendue, et tout le monde veut toute l'histoire.",
  "The first question in any debugging session; gucken is casual everyday German — in the south you'd hear schauen.": "La première question de toute séance de débogage ; gucken est de l'allemand quotidien décontracté — dans le sud, vous entendrez schauen.",
  "The fixed idiom, literally 'I don't trust her across the road' — stronger and more colourful than plain 'Ich trau ihr nicht'. Friends-only gossip register, never about a colleague within earshot.": "L'expression figée, littéralement 'je ne lui fais pas confiance en travers du chemin' — plus forte et plus imagée que le simple 'Ich trau ihr nicht'. Registre de ragot réservé aux amis, jamais à propos d'un collègue à portée d'oreille.",
  "THE fixed phrase for going independent — works with your boss, your bank and your friends alike. Keep the matching word: 'ich mache mich selbstständig', 'du machst dich selbstständig'.": "LA formule figée pour se mettre à son compte — elle fonctionne avec votre patron, votre banque et vos amis. Gardez le mot qui va avec : 'ich mache mich selbstständig', 'du machst dich selbstständig'.",
  "The flare-up warning. Move it to the side; never pour water on.": "L'avertissement contre l'embrasement. Écartez-la ; ne jamais verser d'eau dessus.",
  "The Friday-evening brief. 'mitdenken' = to think along with it. The relative 'wo' instead of 'bei dem' is casual spoken German and completely normal here — the correct version would sound like a job application.": "Le résumé du vendredi soir. 'mitdenken' = réfléchir avec. Le relatif 'wo' au lieu de 'bei dem' est de l'allemand parlé décontracté et parfaitement normal ici — la version correcte sonnerait comme une lettre de motivation.",
  "The friendly decline of a taste — the 'so' is doing all the softening. For hobbies, genres, food, nights out; never about a person. Bare 'Nicht mein Ding.' is blunter but still fine among friends.": "Le refus amical d'un goût — c'est le 'so' qui adoucit tout. Pour les loisirs, les genres, la nourriture, les sorties ; jamais à propos d'une personne. Le nu 'Nicht mein Ding.' est plus abrupt mais reste correct entre amis.",
  "The German friendship accounting system in one line: nobody splits every bill, you just take turns. Naming the last round is what makes the offer stick instead of starting a polite scuffle over the bill.": "Le système comptable de l'amitié allemande en une ligne : personne ne partage chaque addition, on alterne. Nommer la dernière tournée, c'est ce qui fait tenir l'offre au lieu de déclencher une escarmouche polie autour de l'addition.",
  "The German ID card — der Perso in casual speech.": "La carte d'identité allemande — der Perso à l'oral décontracté.",
  "THE gossip verb: 'über jemanden lästern' (über + Akkusativ) = to talk about someone behind their back. Mildly naughty rather than evil — a good chunk of German friendship maintenance happens while lästern.": "LE verbe du ragot : 'über jemanden lästern' (über + accusatif) = parler de quelqu'un dans son dos. Plutôt coquin que méchant — une bonne part de l'entretien des amitiés allemandes se fait en lästern.",
  "THE gym-bro question; casual, between guys who lift": "LA question des habitués de la salle ; décontractée, entre gens qui soulèvent de la fonte",
  "The hedge 'eher' is key — Germans rarely self-label without it. Safe self-description among friends.": "L'atténuateur 'eher' est essentiel — les Allemands s'étiquettent rarement sans lui. Autodescription sans risque entre amis.",
  "The hike itself; casually also 'die Tour'.": "La randonnée elle-même ; de façon décontractée, aussi 'die Tour'.",
  "The honest cost warning. Under a hundred euros, most people simply pay.": "L'avertissement honnête sur le prix. En dessous de cent euros, la plupart des gens paient sans discuter.",
  "The honest warning, issued once and remembered forever by flatmates.": "L'avertissement honnête, prononcé une fois et retenu à jamais par les colocataires.",
  "The hopeful announcement after a crisis — 'einen Neuanfang wagen' is the fixed collocation (literally 'dare a new beginning'). Friends will nod supportively and worry privately.": "L'annonce pleine d'espoir après une crise — 'einen Neuanfang wagen' est la collocation figée (littéralement 'oser un nouveau départ'). Les amis hocheront la tête avec soutien et s'inquiéteront en privé.",
  "The hopeful walk-in confession. Sunday lunch and Friday evening genuinely need a booking in Germany; 'geht trotzdem was?' is casual but completely fine to say to staff.": "L'aveu plein d'espoir de celui qui entre sans réserver. Le déjeuner du dimanche et le vendredi soir exigent vraiment une réservation en Allemagne ; 'geht trotzdem was?' est décontracté mais tout à fait correct à dire au personnel.",
  "The host's standard warm goodbye at the door, informal.": "Le au revoir chaleureux standard de l'hôte sur le pas de la porte, informel.",
  "THE idiom for total incomprehension — casual, universally known. A learner using it always gets a laugh and instant goodwill.": "L'expression par excellence de l'incompréhension totale — décontractée, connue de tous. Un apprenant qui l'emploie récolte toujours un rire et une sympathie immédiate.",
  "The informal general recommendation question. Add a category or place when it is not already clear from the conversation.": "La question de recommandation générale, en registre informel. Ajoutez une catégorie ou un lieu quand la conversation ne les rend pas déjà évidents.",
  "the key de-escalation and warmth line in mixed-belief couples and friendships; sincere register": "la phrase clé pour désamorcer et réchauffer, dans les couples et amitiés aux croyances différentes ; registre sincère",
  "The late-summer warning. Cover your drink — the wasp finds it anyway.": "L'avertissement de fin d'été. Couvrez votre verre — la guêpe le trouvera quand même.",
  "The lazy option among friends when everyone ate roughly the same — 'durch drei machen' or 'durch drei teilen'. It's a choice, not a necessity: genuinely separate bills are no trouble at all in Germany.": "L'option paresseuse entre amis quand tout le monde a mangé à peu près la même chose — 'durch drei machen' ou 'durch drei teilen'. C'est un choix, pas une nécessité : des additions vraiment séparées ne posent aucun problème en Allemagne.",
  "THE modern smalltalk opener — colleagues, dates, new flatmates. Has largely replaced weather talk. Du-form for anyone you're casual with.": "L'ouverture moderne du small talk — collègues, rendez-vous, nouveaux colocataires. Elle a largement remplacé la météo. Forme en du avec tous ceux qu'on tutoie.",
  "The modern standard framing, used in public health and everyday talk alike. 'der Alkoholiker' is neutral-clinical; 'der Säufer' (drunkard) is the slur to avoid.": "La formulation standard moderne, employée en santé publique comme dans la conversation ordinaire. 'der Alkoholiker' est neutre-clinique ; 'der Säufer' (poivrot) est l'insulte à éviter.",
  "the modern word for conspiracy-rambling; informal and very common now": "le mot moderne pour le délire complotiste ; informel et très courant aujourd'hui",
  "The most common casual check-in — short for Wie geht es?": "La prise de nouvelles décontractée la plus courante — abrégé de Wie geht es?",
  "The most disarming repair line in German: admits BOTH that they were right and that you went too far. Costs pride, buys peace. Partners and close friends.": "La phrase de réparation la plus désarmante en allemand : elle admet À LA FOIS que l'autre avait raison et que vous êtes allé trop loin. Coûte de la fierté, achète la paix. Partenaires et amis proches.",
  "The most famous Zeugnis code line: tried hard, achieved nothing. Also used jokingly among friends: 'Naja, ich war stets bemüht.'": "La formule codée la plus célèbre du Zeugnis : s'est donné du mal, n'a rien obtenu. Employée aussi en plaisantant entre amis : 'Naja, ich war stets bemüht.'",
  "THE music smalltalk question, du-form. The 'so' makes it casual — literally 'what do you listen to, like?'. Standard on dates and new friendships.": "LA question de small talk sur la musique, forme en du. Le 'so' la rend décontractée — littéralement 'tu écoutes quoi, en gros ?'. Standard aux rendez-vous et dans les amitiés naissantes.",
  "The normal everyday phrase — 'meine Periode' sounds medical, 'meine Regel' a bit clinical and older. Completely neutral with friends and partners; at work most people say nothing at all.": "L'expression normale du quotidien — 'meine Periode' sonne médical, 'meine Regel' un peu clinique et daté. Tout à fait neutre entre amis et en couple ; au travail, la plupart des gens n'en disent rien du tout.",
  "The order that avoids regret. Half a percent matters less than one good extra.": "L'ordre qui évite les regrets. Un demi-point compte moins qu'une bonne option en plus.",
  "The other direction. Note the dative: jemandem kündigen. Colloquial 'Ich wurde gekündigt' is widespread but strictly wrong.": "L'autre sens. Notez le datif : jemandem kündigen. Le familier 'Ich wurde gekündigt' est répandu mais, à la rigueur, incorrect.",
  "The permission that keeps friendships alive through a separation.": "La permission qui maintient les amitiés en vie à travers une séparation.",
  "The phone-only goodbye — literally 'until we hear each other again', where face to face it's 'Auf Wiedersehen'. Saying 'Auf Wiedersehen' down the phone is the classic learner slip that natives clock instantly. Formal register; with friends you end on 'Tschüss!' or 'Ciao!'": "L'au revoir réservé au téléphone — littéralement 'jusqu'à ce qu'on se réentende', là où en face à face on dit 'Auf Wiedersehen'. Dire 'Auf Wiedersehen' au téléphone est la faute d'apprenant classique que les natifs repèrent instantanément. Registre formel ; entre amis, on termine par 'Tschüss!' ou 'Ciao!'",
  "The playful threat escalation — 'gleich' (in a second) gives fair warning. 'kitzlig sein' = to be ticklish: 'Bist du kitzlig?'": "L'escalade de menace joueuse — 'gleich' (dans une seconde) donne un avertissement loyal. 'kitzlig sein' = être chatouilleux : 'Bist du kitzlig?'",
  "The polite exit that puts the other person first — you're not ending the call, you're freeing them. Very common with friends and family; German needs no equivalent of the English 'go'.": "La sortie polie qui fait passer l'autre en premier — vous ne mettez pas fin à l'appel, vous le libérez. Très courant entre amis et en famille ; l'allemand n'a pas besoin d'équivalent du 'go' anglais.",
  "The positive mirror. 'Etwas/nichts/viel von jemandem halten' is THE casual pattern for rating people.": "Le miroir positif. 'Etwas/nichts/viel von jemandem halten' est LA tournure décontractée pour juger les gens.",
  "The pre-emptive strike, and the whole trick of money between friends: say it before they have to. After that nobody feels weird about the ten euros.": "L'initiative anticipée, et toute l'astuce de l'argent entre amis : dis-le avant qu'on ait à te le demander. Après ça, plus personne ne se sent bizarre pour dix euros.",
  "The promise that keeps friendships": "La promesse qui préserve les amitiés",
  "The proud line — drop it casually among friends and watch the questions start.": "La phrase fière — glissez-la l'air de rien entre amis et regardez les questions arriver.",
  "The question betrayed partners actually ask their friends. Verzeihen is the deep word — 'entschuldigen' would be absurdly light for infidelity.": "La question que les partenaires trompés posent réellement à leurs amis. Verzeihen est le mot profond — 'entschuldigen' serait d'une légèreté absurde pour une infidélité.",
  "The quiet ending of many friendships, described without accusation.": "La fin discrète de bien des amitiés, décrite sans reproche.",
  "The reciprocity ledger of friendship — informal, unwritten, never forgotten.": "Le grand livre de la réciprocité amicale — informel, non écrit, jamais oublié.",
  "The refusal that protects the friendship by naming the rule, not the person.": "Le refus qui protège l'amitié en nommant la règle plutôt que la personne.",
  "The saying as Germans actually quote it in heartbreak conversations. Friends deploy it as a warning against taking someone back; the counter-camp answers 'Menschen können sich ändern'.": "Le dicton tel que les Allemands le citent réellement dans les conversations de chagrin d'amour. Les amis le déploient comme un avertissement contre le fait de reprendre quelqu'un ; le camp adverse répond 'Menschen können sich ändern'.",
  "The sentence that softens hard truths between friends.": "La phrase qui adoucit les vérités dures entre amis.",
  "The sequence that avoids visible edges. Professionals call it 'vorschneiden'.": "La séquence qui évite les démarcations visibles. Les professionnels appellent cela 'vorschneiden'.",
  "The set reply when someone asks for you by name. 'der Apparat' is the old word for a telephone set and survives almost nowhere else — nobody calls a phone an Apparat any more, but everyone says 'am Apparat'. Neutral-to-formal; with friends it's just 'Ja, ich bin's.'": "La réponse consacrée quand on vous demande par votre nom. 'der Apparat' est le vieux mot pour un poste téléphonique et ne survit presque nulle part ailleurs — plus personne n'appelle un téléphone un Apparat, mais tout le monde dit 'am Apparat'. Neutre à formel ; entre amis, c'est simplement 'Ja, ich bin's.'",
  "The slow-burn version: 'langsam' means the patience is running out, not gone. Drop it and you get the sharp 'Jetzt reicht's!', which is a full stop, not a warning.": "La version à combustion lente : 'langsam' signifie que la patience s'épuise, pas qu'elle est épuisée. Retirez-le et vous obtenez le tranchant 'Jetzt reicht's!', qui est un point final, pas un avertissement.",
  "The so makes the question casual — 'what do you do, generally?' The small-talk classic.": "Le so rend la question décontractée — 'tu fais quoi, en gros ?' Le classique du small talk.",
  "The softest possible way to say 'that's wrong'. 'draufschauen' keeps it casual; 'prüfen' or 'kontrollieren' make it sound like you're demanding an investigation.": "La façon la plus douce possible de dire 'c'est faux'. 'draufschauen' garde le ton décontracté ; 'prüfen' ou 'kontrollieren' donnent l'impression que vous exigez une enquête.",
  "The solemn one — anniversaries, vows, letters. Partner only; too big for casual goodbyes.": "La formule solennelle — anniversaires, vœux, lettres. Réservée au partenaire ; trop grande pour un au revoir décontracté.",
  "The spoken du-command is 'Klick'; a more formal warning is 'Klicken Sie nicht auf den Link'.": "L'ordre oral en du est 'Klick' ; un avertissement plus formel serait 'Klicken Sie nicht auf den Link'.",
  "The standard ask on a night out — friendly and low-pressure, works with friends and strangers alike. Fills an obvious gap: the pack covers drinks, the bill and the door queue but never the dancing.": "La demande standard en soirée — amicale et sans pression, elle marche avec des amis comme avec des inconnus. Elle comble un manque évident : le lot couvre les boissons, l'addition et la file d'entrée, mais jamais la danse.",
  "The standard closing courtesy among friends. Expected, and noticed if forgotten.": "La politesse de clôture standard entre amis. Attendue, et remarquée si on l'oublie.",
  "The standard earworm complaint, informal. Often followed by singing it and infecting everyone else.": "La plainte standard face à un ver d'oreille, informelle. Souvent suivie du fait qu'on le chante et qu'on contamine tout le monde.",
  "The standard evening sign-off — always 'ins Bett'. Slangier: 'Ich geh pennen.' Add 'Gute Nacht' and you're free to leave.": "Le mot de la fin habituel du soir — toujours 'ins Bett'. Plus argotique : 'Ich geh pennen.' Ajoutez 'Gute Nacht' et vous êtes libre de partir.",
  "The standard go-live announcement to friends and Discord; streamen conjugates like any German verb (gestreamt).": "L'annonce standard du passage en direct aux amis et sur Discord ; streamen se conjugue comme n'importe quel verbe allemand (gestreamt).",
  "The standard sigh after any pay-rise or salary talk; casual, universal": "Le soupir standard après toute négociation ou augmentation de salaire ; décontracté, universel",
  "the standard verb; coden is its casual twin": "le verbe standard ; coden en est le jumeau décontracté",
  "The standard warm reply you WILL hear — 'echt' makes it casual and sincere. Just say 'Danke!', don't argue.": "La réponse chaleureuse standard que vous ENTENDREZ — 'echt' la rend décontractée et sincère. Dites simplement 'Danke!', ne discutez pas.",
  "the standard way to disclose a serious rift; neutral register, works with friends and colleagues alike": "la façon standard d'annoncer une rupture sérieuse ; registre neutre, valable avec les amis comme avec les collègues",
  "The standard way to promise a return invitation at the door, informal.": "La façon standard de promettre une invitation en retour sur le pas de la porte, informel.",
  "the standard word; casually 'die Muckibude' or just 'das Gym'": "le mot standard ; de façon décontractée 'die Muckibude' ou simplement 'das Gym'",
  "The stylist asks this at the end; reinmachen is casual spoken German": "Le coiffeur pose cette question à la fin ; reinmachen est de l'allemand parlé décontracté",
  "The universal German 'huh?' — totally normal between partners and friends, rude to strangers or your boss (there: 'Wie bitte?'). Learn to hear it too: it signals confusion, not hostility.": "Le 'hein ?' allemand universel — parfaitement normal en couple et entre amis, impoli avec des inconnus ou votre chef (là : 'Wie bitte?'). Apprenez aussi à l'entendre : il signale la confusion, pas l'hostilité.",
  "The universal gossip opener among friends and colleagues — it announces juicy news the way a drumroll does. With content: 'Hast du schon gehört, dass ...?'. Gen Z also announces it with the English loan 'Drama': 'Es gab mal wieder Drama.'": "L'ouverture universelle du ragot entre amis et collègues — elle annonce une nouvelle croustillante comme un roulement de tambour. Avec le contenu : 'Hast du schon gehört, dass ...?'. La génération Z l'annonce aussi avec l'emprunt anglais 'Drama' : 'Es gab mal wieder Drama.'",
  "the universal hotline complaint — said to the agent who finally picks up, or vented to friends afterwards; 'hängen' is the fixed verb": "la plainte universelle des hotlines — dite à l'agent qui décroche enfin, ou déversée ensuite auprès des amis ; 'hängen' est le verbe consacré",
  "the universal leg-day complaint; casual": "la plainte universelle du jour des jambes ; décontractée",
  "The vague 'die' (them = politicians) is characteristic of casual political talk. Can spark generational debate, so read the room.": "Le vague 'die' (eux = les politiques) est typique du discours politique décontracté. Cela peut déclencher un débat entre générations, alors observez l'auditoire.",
  "THE verdict on a celebrity gone arrogant — literally 'lifted off' the ground; also works for ex-friends who got successful": "LE verdict sur une célébrité devenue arrogante — littéralement 'décollé' du sol ; vaut aussi pour d'anciens amis qui ont réussi",
  "The warning against illegal puppy trade. Cheap, sick, and it funds more of it.": "L'avertissement contre le trafic illégal de chiots. Pas cher, malade, et cela finance la suite.",
  "The warning light before something honest: 'Versteh mich nicht falsch, aber ...'. Exactly as in English, whatever follows the 'aber' is the real message.": "Le voyant d'avertissement avant quelque chose de franc : 'Versteh mich nicht falsch, aber ...'. Exactement comme en anglais, ce qui suit le 'aber' est le vrai message.",
  "The written warning from an employer or lawyer — one step before consequences.": "L'avertissement écrit d'un employeur ou d'un avocat — une étape avant les conséquences.",
  "This impersonal passive is a playful way to announce an unavoidable routine without repeatedly saying 'you'.": "Ce passif impersonnel est une façon ludique d'annoncer une routine inévitable sans répéter 'tu'.",
  "Time comment": "Remarque sur l'heure",
  "To friends or your partner right after trying a new word. Invites a gentle correction.": "À des amis ou à son partenaire juste après avoir essayé un mot nouveau. Invite à une correction douce.",
  "TOP of the ladder, MOST SEVERE — ends friendships, starts fights, and counts as criminal Beleidigung. Understand it instantly when you hear it; there is almost no situation where you should say it.": "SOMMET de l'échelle, LE PLUS GRAVE — met fin à des amitiés, déclenche des bagarres et constitue une Beleidigung pénalement punissable. Comprenez-le immédiatement quand vous l'entendez ; il n'existe presque aucune situation où vous devriez le dire.",
  "TRAP: 'die Fabrik' is a factory, not fabric. Fabric is 'der Stoff' — which itself also means 'material' and, colloquially, 'drugs'. German enjoys this.": "PIÈGE : 'die Fabrik' est une usine, pas du tissu. Le tissu, c'est 'der Stoff' — qui signifie aussi 'matière' et, familièrement, 'drogue'. L'allemand s'en amuse.",
  "Two words that stop a small hand. 'Vorsicht' works alone as a warning.": "Deux mots qui arrêtent une petite main. 'Vorsicht' fonctionne seul comme avertissement.",
  "Typical reply": "Réponse typique",
  "über die Runden kommen = make ends meet; idiomatic, signals real financial strain without drama; friends and family": "über die Runden kommen = joindre les deux bouts ; idiomatique, signale une véritable tension financière sans dramatiser ; amis et famille",
  "überweisen + dative person — sending money person-to-person. How friends settle up in Germany.": "überweisen + personne au datif — envoyer de l'argent de personne à personne. C'est ainsi que les amis règlent leurs comptes en Allemagne.",
  "um einen Gefallen bitten — the formal opening of informal help. Germans appreciate the framing.": "um einen Gefallen bitten — l'ouverture formelle d'une aide informelle. Les Allemands apprécient ce cadrage.",
  "umrühren separable; anbrennen = burn onto the pot bottom — different from verbrennen (burn up); casual kitchen command, du-form.": "umrühren est séparable ; anbrennen = attacher au fond de la casserole — différent de verbrennen (brûler entièrement) ; ordre décontracté de cuisine, forme en du.",
  "Understatement instead of criticism: negating an enthusiastic word ('der Hammer' = amazing, colloquial) is the polite German way of saying something was bad. The 'jetzt' is a softening filler, nothing to do with time. Informal — fine about a film or a restaurant, not about someone's cooking to their face.": "L'euphémisme à la place de la critique : nier un mot enthousiaste ('der Hammer' = génial, familier) est la façon polie qu'ont les Allemands de dire que c'était mauvais. Le 'jetzt' est un mot de remplissage adoucissant, sans rapport avec le temps. Informel — ça passe pour un film ou un restaurant, pas pour la cuisine de quelqu'un dite en face.",
  "Unlocks": "Déblocages",
  "Urgent": "Urgent",
  "Urgent warning": "Avertissement urgent",
  "Verb-first inversion ('ist das ...!') is how German does 'this is SO ...' — works with any adjective: 'Ist das kalt!'. 'Boah' is the everyday spoken wow: perfect with friends and family, a shade too casual at a formal dinner, where 'Ist das lecker!' on its own does the job.": "L'inversion avec le verbe en tête ('ist das ...!') est la façon allemande de dire 'c'est TELLEMENT ...' — elle marche avec n'importe quel adjectif : 'Ist das kalt!'. 'Boah' est le wow oral du quotidien : parfait entre amis et en famille, un cran trop décontracté lors d'un dîner formel, où 'Ist das lecker!' tout seul suffit.",
  "verschreien — jinxing by saying. The warning shouted across German offices daily.": "verschreien — porter la poisse en le disant. L'avertissement crié chaque jour dans les bureaux allemands.",
  "verschwitzen — sweating an appointment away: forgetting it entirely. Casual, honest, forgivable once.": "verschwitzen — transpirer un rendez-vous jusqu'à l'oubli total. Décontracté, honnête, pardonnable une fois.",
  "versterben = formal register: obituaries, doctors, official letters. Using it in casual speech sounds distant; using sterben in an obituary sounds blunt.": "versterben = registre formel : avis de décès, médecins, courriers officiels. À l'oral décontracté, cela sonne distant ; sterben dans un avis de décès sonne brutal.",
  "verstoßen gegen + Akkusativ; mit etwas rechnen müssen is the standard warning of consequences.": "verstoßen gegen + accusatif ; mit etwas rechnen müssen est l'avertissement standard des conséquences.",
  "Very casual slang for friends": "Argot très décontracté pour parler d'amis",
  "very casual, friends only; 'Muckibude' (muscle shack) is jokey-affectionate gym slang — 'Fitnessstudio' is the neutral word for it": "très décontracté, entre amis seulement ; 'Muckibude' (la baraque à muscles) est de l'argot de salle blagueur et affectueux — 'Fitnessstudio' en est le mot neutre",
  "very casual, said just before a penalty; 'der' instead of 'er' is typical fan speech": "très décontracté, dit juste avant un penalty ; 'der' au lieu de 'er' est typique du parler des supporters",
  "Very casual: 'ne' = 'eine', 'probier mal' softens it. With friends, not in writing.": "Très décontracté : 'ne' = 'eine', 'probier mal' adoucit. Entre amis, pas à l'écrit.",
  "Very colloquial and rough. Here 'kein Schwanz' means nobody, not a body part. It can sound crude or dated, so it is more useful to recognise than copy.": "Très familier et rugueux. Ici, 'kein Schwanz' signifie personne, pas une partie du corps. Cela peut sonner cru ou daté ; mieux vaut le reconnaître que le reprendre.",
  "Very colloquial gripe — 'etwas auf die Reihe kriegen' = to get one's act together. Everyday frustration, not extreme.": "Ronchonnement très familier — 'etwas auf die Reihe kriegen' = arriver à s'organiser, à faire les choses. Frustration ordinaire, rien d'extrême.",
  "Very common (informal alternative to 'Die Rechnung bitte')": "Très courant (alternative informelle à 'Die Rechnung bitte')",
  "Very common casual slang": "Argot décontracté très courant",
  "Very common colloquial verb for losing your temper": "Verbe familier très courant pour dire qu'on perd son sang-froid",
  "Very common colloquial; about losing your temper, not going crazy.": "Très courant en registre familier ; il s'agit de perdre son calme, pas de devenir fou.",
  "Very common in conversation and informal writing; the standard, register-neutral alternative is 'Das ergibt Sinn'.": "Très courant dans la conversation et à l'écrit informel ; l'alternative standard, neutre de registre, est 'Das ergibt Sinn'.",
  "Very common leisure activity": "Loisir très courant",
  "Very common, casual — Bock = desire/appetite": "Très courant, décontracté — Bock = l'envie",
  "Very common, casual — literally 'that's sausage to me'": "Très courant, décontracté — littéralement 'ça m'est saucisse'",
  "Very common, direct — friends or real annoyance": "Très courant, direct — entre amis ou en cas d'agacement réel",
  "Very rude — slightly less aggressive than 'Halt die Fresse' but still hostile. Rough banter possible among close friends only.": "Très impoli — un peu moins agressif que 'Halt die Fresse' mais toujours hostile. Une vanne rugueuse n'est possible qu'entre amis proches.",
  "Very rude and aggressive — 'Fresse' is a vulgar word for face/mouth. Among very close friends occasionally joking; to anyone else it invites escalation.": "Très impoli et agressif — 'Fresse' est un mot vulgaire pour le visage ou la bouche. Entre amis très proches, parfois pour rire ; envers quiconque d'autre, cela invite à l'escalade.",
  "vorbeischauen — looking past: the casual visit. 'auf einen Kaffee' — the unit of neighbourliness.": "vorbeischauen — passer voir : la visite décontractée. 'auf einen Kaffee' — l'unité de mesure du bon voisinage.",
  "Vorsicht + statement — the standard kitchen warning shape.": "Vorsicht + phrase — la forme standard de l'avertissement en cuisine.",
  "Vulgar and confrontational. It challenges what someone has done and can start an argument, so do not use it as a casual question.": "Vulgaire et frontal. Cela remet en cause ce que quelqu'un a fait et peut déclencher une dispute ; ne l'employez donc pas comme une question anodine.",
  "VULGAR but not aggressive — the honest shocked reaction between friends, and much warmer than a polite murmur when the news is genuinely bad. Never at work or with your partner's parents; the clean versions are 'Ach du Schreck!' or 'Oh nein!'": "VULGAIRE mais pas agressif — la réaction de choc honnête entre amis, bien plus chaleureuse qu'un murmure poli quand la nouvelle est vraiment mauvaise. Jamais au travail ni chez les parents de votre partenaire ; les versions propres sont 'Ach du Schreck!' ou 'Oh nein!'",
  "Vulgar metaphor for pointless competitive showing off, often between men. Avoid it in formal or professional conversation.": "Métaphore vulgaire pour une surenchère de vantardise sans objet, souvent entre hommes. À éviter dans une conversation formelle ou professionnelle.",
  "Vulgar-casual: Willst du mich verarschen? = are you kidding me?": "Vulgaire-décontracté : Willst du mich verarschen? = tu te fous de moi ?",
  "Vulgar-ish (from Arsch = arse), moderately strong — disbelief or being wound up. Friends and close colleagues only; not to your boss or strangers.": "Plutôt vulgaire (de Arsch, le cul), moyennement fort — incrédulité ou sentiment qu'on se moque de vous. Amis et collègues proches seulement ; pas avec votre chef ni des inconnus.",
  "Vulgar-ish (from Arsch = arse). Fine among friends, avoid with strangers or at work.": "Plutôt vulgaire (de Arsch, le cul). Ça passe entre amis, à éviter avec des inconnus ou au travail.",
  "VULGAR, and deliberately so — this is the anti-platitude. 'schönreden' = to talk something up, to make it sound better than it is; refusing to do it is a form of respect. Between friends this lands far better than 'Alles wird gut.'": "VULGAIRE, et volontairement — c'est l'anti-platitude. 'schönreden' = enjoliver quelque chose, le faire paraître meilleur qu'il n'est ; refuser de le faire est une forme de respect. Entre amis, cela passe bien mieux que 'Alles wird gut.'",
  "Warm but LIGHT: for friends, family, siblings — or very early dating. It is NOT the deep-moment line for a partner; swapping it in for 'Ich liebe dich' can even feel like a downgrade. (French does the same trick: 'je t'aime beaucoup' is weaker than 'je t'aime'.)": "Chaleureux mais LÉGER : pour les amis, la famille, les frères et sœurs — ou tout début de relation. Ce n'est PAS la phrase du grand moment avec un partenaire ; la substituer à 'Ich liebe dich' peut même être ressenti comme un recul. (Le français fait le même tour : 'je t'aime beaucoup' est plus faible que 'je t'aime'.)",
  "Warm casual goodbye — informal (du), friends only": "Au revoir chaleureux et décontracté — informel (du), entre amis seulement",
  "warm compliment for partner or close friends; stronger than 'gut'": "compliment chaleureux pour un partenaire ou des amis proches ; plus fort que 'gut'",
  "Warm compliment, safe in any casual context.": "Compliment chaleureux, sans risque dans tout contexte décontracté.",
  "Warm door greeting to friends (ihr). One person: 'Komm rein!'; formal: 'Kommen Sie rein!'": "Accueil chaleureux à la porte pour des amis (ihr). Une seule personne : 'Komm rein!' ; formel : 'Kommen Sie rein!'",
  "Warm du-form for friends and family. Softer and more personal than the formal Beileid formulas.": "Forme en du, chaleureuse, pour les amis et la famille. Plus douce et plus personnelle que les formules de condoléances officielles.",
  "Warm encouragement — comparative + 'als du denkst'. (French shown to a woman; to a man: 'plus courageux'.) Register warning for the opposite: calling someone 'feige' (cowardly) is a genuine insult in German, never banter.": "Encouragement chaleureux — comparatif + 'als du denkst'. (La version française s'adresse à une femme ; à un homme : 'plus courageux'.) Avertissement de registre pour le contraire : traiter quelqu'un de 'feige' (lâche) est une vraie insulte en allemand, jamais une plaisanterie.",
  "Warm encouragement from friends — 'dranbleiben' = stick with it. Also what hosts say before a break: 'Bleibt dran!' / formal 'Bleiben Sie dran!'": "Encouragement chaleureux d'amis — 'dranbleiben' = s'accrocher. C'est aussi ce que disent les animateurs avant une pause : 'Bleibt dran!' / au formel 'Bleiben Sie dran!'",
  "Warm goodbye — informal (du), friends only": "Au revoir chaleureux — informel (du), entre amis seulement",
  "Warm team-spirit reassurance after a rough patch — 'hinkriegen' (colloquial: to manage/fix) plus 'wir' says the relationship is bigger than the fight. Constructive, hopeful, partner or close friends.": "Réassurance chaleureuse en mode équipe après une passe difficile — 'hinkriegen' (familier : arriver à réparer) plus 'wir' dit que la relation est plus grande que la dispute. Constructif, plein d'espoir, pour un partenaire ou des amis proches.",
  "Warm toast among friends, couples, teams celebrating something together. Follows or replaces 'Prost'.": "Toast chaleureux entre amis, en couple, en équipe quand on fête quelque chose ensemble. Suit ou remplace 'Prost'.",
  "Warm, casual encouragement before a challenge. 'You've got this' is the most natural English equivalent.": "Encouragement chaleureux et décontracté avant une épreuve. L'équivalent anglais le plus naturel est 'You've got this'.",
  "Warning": "Avertissement",
  "WARNING — this is the wrong move mid-rant and lands as dismissive, exactly like English 'calm down'. Learn it to recognise it; if you want to defuse, use 'Das würde mich genauso fertigmachen' first.": "AVERTISSEMENT — en pleine tirade, c'est le mauvais geste et cela passe pour du mépris, exactement comme le 'calm down' anglais. Apprenez-le pour le reconnaître ; si vous voulez désamorcer, dites d'abord 'Das würde mich genauso fertigmachen'.",
  "Warning the neighbours BEFORE the noise is what stops the complaint ever happening — said at the door or on a note in the stairwell. 'sorry schon mal im Voraus' is the light, half-joking apology-in-advance formula.": "Prévenir les voisins AVANT le bruit, c'est ce qui empêche la plainte de naître — dit à la porte ou sur un mot dans la cage d'escalier. 'sorry schon mal im Voraus' est la formule légère et à moitié blagueuse d'excuse anticipée.",
  "Weather": "Météo",
  "What you ask the neighbours during an outage; weg sein = to be gone (very common colloquial)": "Ce qu'on demande aux voisins pendant une panne ; weg sein = être coupé (très courant en registre familier)",
  "What your investment earns; 'Rendite abwerfen' = to yield a return, colloquially also 'Rendite machen'": "Ce que rapporte votre placement ; 'Rendite abwerfen' = dégager un rendement, familièrement aussi 'Rendite machen'",
  "Written German too": "Aussi à l'écrit",
  "You always 'hört sich' a Sprachnachricht 'an' — never just 'hören'. die Sprachnachricht is a genuine fault line between friends, and declaring you don't listen to them is practically a personality statement. The reproach from the other side: 'Deine Sprachnachricht war sieben Minuten lang.'": "Un Sprachnachricht, on se l'écoute ('sich anhören') — jamais simplement 'hören'. die Sprachnachricht est une véritable ligne de fracture entre amis, et déclarer qu'on ne les écoute pas est pratiquement une déclaration d'identité. Le reproche d'en face : 'Deine Sprachnachricht war sieben Minuten lang.'",
  "youth slang from 'suchten' (die Sucht = addiction): hat durchgesuchtet; 'binge-watchen' also works": "argot des jeunes venu de 'suchten' (die Sucht = l'addiction) : hat durchgesuchtet ; 'binge-watchen' marche aussi",
  "youth slang intensifier/negative: 'Mein Ping ist übel' = my ping is terrible. Can also intensify positively: 'übel gut'": "intensificateur/négatif de l'argot des jeunes : 'Mein Ping ist übel' = mon ping est atroce. Peut aussi intensifier positivement : 'übel gut'",
  "Youth/casual slang, mild — genuine or mocking congratulation depending on tone. Friends and younger colleagues; sounds odd from/to older strangers.": "Argot des jeunes et du quotidien, doux — félicitation sincère ou moqueuse selon le ton. Amis et collègues plus jeunes ; sonne bizarre venant d'inconnus plus âgés ou adressé à eux.",
  "zu lebenslanger Haft verurteilt = sentenced to life imprisonment; lebenslanges Lernen = lifelong learning. The parallel adjective lebenslaenglich is the usual word in court reporting and can stand on its own: er bekam lebenslaenglich.": "zu lebenslanger Haft verurteilt = condamné à la réclusion à perpétuité ; lebenslanges Lernen = apprentissage tout au long de la vie. L'adjectif parallèle lebenslaenglich est le mot habituel dans les comptes rendus judiciaires et peut tenir seul : er bekam lebenslaenglich.",
  "zunächst and bislang bracket the timeline; es das geblieben — das stands for harmlos.": "zunächst et bislang encadrent la chronologie ; es das geblieben — das renvoie à harmlos.",
  "zurückzahlen — paying back. The clause that keeps the friendship intact.": "zurückzahlen — rembourser. La proposition qui laisse l'amitié intacte.",
};
